import { useState, useMemo, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";
import {
  Search,
  ChevronRight,
  Briefcase,
  Code2,
  Palette,
  Users,
  BarChart2,
  Settings,
  Megaphone,
  FlaskConical,
  ArrowUpDown,
  Trash2,
  X,
  AlertTriangle,
  Download,
} from "lucide-react";
import { format } from "date-fns";
import { toast } from "sonner";
import type { PastJob } from "@/pages/Index";

// ─── Types ───────────────────────────────────────────────────────────────────

interface JobsOverviewCardProps {
  jobs: PastJob[];
  loading: boolean;
  onSelectJob: (jobId: string) => void;
  onDeleteJobs?: (jobIds: string[]) => Promise<void>;
}

type SortOption = "latest" | "oldest" | "name_asc" | "name_desc" | "resumes_desc" | "score_desc";

// ─── Helpers ─────────────────────────────────────────────────────────────────

const PAGE_SIZE = 10;

const JOB_ICONS = [Briefcase, Code2, Palette, Users, BarChart2, Settings, Megaphone, FlaskConical];

const ICON_BG_COLORS = [
  "bg-blue-100 text-blue-600",
  "bg-violet-100 text-violet-600",
  "bg-pink-100 text-pink-600",
  "bg-amber-100 text-amber-600",
  "bg-teal-100 text-teal-600",
  "bg-orange-100 text-orange-600",
  "bg-emerald-100 text-emerald-600",
  "bg-indigo-100 text-indigo-600",
];

function getJobIconProps(title: string | null, index: number) {
  const lower = (title ?? "").toLowerCase();
  let iconIndex = index % JOB_ICONS.length;

  if (lower.includes("engineer") || lower.includes("developer") || lower.includes("dev") || lower.includes("code")) {
    iconIndex = 1;
  } else if (lower.includes("design") || lower.includes("ui") || lower.includes("ux")) {
    iconIndex = 2;
  } else if (lower.includes("manager") || lower.includes("hr") || lower.includes("talent") || lower.includes("recrui")) {
    iconIndex = 3;
  } else if (lower.includes("analyt") || lower.includes("data") || lower.includes("scientist")) {
    iconIndex = 4;
  } else if (lower.includes("market") || lower.includes("growth") || lower.includes("content")) {
    iconIndex = 6;
  } else if (lower.includes("research") || lower.includes("science") || lower.includes("lab")) {
    iconIndex = 7;
  }

  return {
    Icon: JOB_ICONS[iconIndex],
    colorClass: ICON_BG_COLORS[iconIndex],
  };
}

function extractEmploymentTags(jdAnalysis: any): string[] {
  if (!jdAnalysis) return [];
  const tags: string[] = [];

  const empType =
    jdAnalysis.employment_type ??
    jdAnalysis.job_type ??
    jdAnalysis.type ??
    jdAnalysis.contract_type ??
    null;

  const workType =
    jdAnalysis.work_type ??
    jdAnalysis.location_type ??
    jdAnalysis.remote ??
    jdAnalysis.work_arrangement ??
    null;

  if (empType && typeof empType === "string") tags.push(empType);
  if (workType && typeof workType === "string") tags.push(workType);

  return tags.filter(Boolean).map((t) => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase());
}

function scoreColor(score: number): string {
  if (score >= 70) return "#22c55e";
  if (score >= 40) return "#f59e0b";
  return "#ef4444";
}

// ─── Circular Score Ring ─────────────────────────────────────────────────────

interface CircularScoreProps {
  score: number | null;
  size?: number;
  strokeWidth?: number;
}

const CircularScore = ({ score, size = 44, strokeWidth = 4 }: CircularScoreProps) => {
  if (score === null) {
    return (
      <div className="flex items-center justify-center" style={{ width: size, height: size }}>
        <span className="text-sm font-medium text-muted-foreground">—</span>
      </div>
    );
  }

  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const progress = Math.min(Math.max(score, 0), 100);
  const dashOffset = circumference - (progress / 100) * circumference;
  const color = scoreColor(progress);

  return (
    <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="-rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke="currentColor"
          strokeWidth={strokeWidth}
          className="text-muted/30"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeDasharray={circumference}
          strokeDashoffset={dashOffset}
          strokeLinecap="round"
        />
      </svg>
      <span
        className="absolute text-[10px] font-bold tabular-nums"
        style={{ color }}
      >
        {Math.round(progress)}%
      </span>
    </div>
  );
};

// ─── Skeleton Row ─────────────────────────────────────────────────────────────

const SkeletonRow = () => (
  <tr className="border-b border-border last:border-0">
    <td className="pl-5 pr-2 py-3.5">
      <Skeleton className="h-4 w-4 rounded" />
    </td>
    <td className="px-4 py-3.5">
      <div className="flex items-center gap-3">
        <Skeleton className="h-9 w-9 rounded-lg shrink-0" />
        <div className="flex flex-col gap-1.5 flex-1 min-w-0">
          <Skeleton className="h-3.5 w-3/4 rounded" />
          <Skeleton className="h-3 w-1/2 rounded" />
        </div>
      </div>
    </td>
    <td className="px-4 py-3.5">
      <Skeleton className="h-4 w-6 rounded" />
    </td>
    <td className="px-4 py-3.5">
      <Skeleton className="h-11 w-11 rounded-full" />
    </td>
    <td className="px-4 py-3.5">
      <Skeleton className="h-5 w-20 rounded-full" />
    </td>
    <td className="px-4 py-3.5">
      <Skeleton className="h-3.5 w-24 rounded" />
    </td>
    <td className="px-4 py-3.5">
      <Skeleton className="h-4 w-4 rounded" />
    </td>
  </tr>
);

// ─── Bulk Action Bar ──────────────────────────────────────────────────────────

interface BulkActionBarProps {
  count: number;
  onClear: () => void;
  onDelete: () => void;
  onExport: () => void;
  deleting: boolean;
}

const BulkActionBar = ({ count, onClear, onDelete, onExport, deleting }: BulkActionBarProps) => (
  <div className="flex items-center justify-between gap-3 px-6 py-3 bg-primary/5 border-b border-primary/20 animate-in slide-in-from-top-1 duration-150">
    <div className="flex items-center gap-2.5">
      <div className="h-5 w-5 rounded-full bg-primary flex items-center justify-center">
        <span className="text-[10px] font-bold text-primary-foreground">{count}</span>
      </div>
      <span className="text-sm font-medium text-foreground">
        {count} job{count !== 1 ? "s" : ""} selected
      </span>
    </div>

    <div className="flex items-center gap-2">
      <Button
        variant="outline"
        size="sm"
        className="h-8 gap-1.5 text-xs"
        onClick={onExport}
      >
        <Download className="h-3.5 w-3.5" />
        Export CSV
      </Button>
      <Button
        variant="outline"
        size="sm"
        className="h-8 gap-1.5 text-xs border-destructive/40 text-destructive hover:bg-destructive hover:text-destructive-foreground hover:border-destructive"
        onClick={onDelete}
        disabled={deleting}
      >
        <Trash2 className="h-3.5 w-3.5" />
        {deleting ? "Deleting…" : "Delete"}
      </Button>
      <button
        onClick={onClear}
        className="h-8 w-8 flex items-center justify-center rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
        aria-label="Clear selection"
      >
        <X className="h-3.5 w-3.5" />
      </button>
    </div>
  </div>
);

// ─── Delete Confirm Dialog ────────────────────────────────────────────────────

interface DeleteConfirmProps {
  count: number;
  onConfirm: () => void;
  onCancel: () => void;
  deleting: boolean;
}

const DeleteConfirmBanner = ({ count, onConfirm, onCancel, deleting }: DeleteConfirmProps) => (
  <div className="flex items-center justify-between gap-3 px-6 py-3 bg-destructive/5 border-b border-destructive/20 animate-in slide-in-from-top-1 duration-150">
    <div className="flex items-center gap-2.5">
      <AlertTriangle className="h-4 w-4 text-destructive shrink-0" />
      <span className="text-sm font-medium text-destructive">
        Delete {count} job{count !== 1 ? "s" : ""}? This cannot be undone.
      </span>
    </div>
    <div className="flex items-center gap-2">
      <Button variant="outline" size="sm" className="h-8 text-xs" onClick={onCancel} disabled={deleting}>
        Cancel
      </Button>
      <Button variant="destructive" size="sm" className="h-8 text-xs gap-1.5" onClick={onConfirm} disabled={deleting}>
        <Trash2 className="h-3.5 w-3.5" />
        {deleting ? "Deleting…" : "Yes, Delete"}
      </Button>
    </div>
  </div>
);

// ─── Main Component ───────────────────────────────────────────────────────────

const JobsOverviewCard = ({ jobs, loading, onSelectJob, onDeleteJobs }: JobsOverviewCardProps) => {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [sortOption, setSortOption] = useState<SortOption>("latest");
  const [page, setPage] = useState(1);
  const [avgScores, setAvgScores] = useState<Record<string, number>>({});

  // Bulk select state
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleting, setDeleting] = useState(false);

  // Fetch average scores for all jobs
  useEffect(() => {
    if (jobs.length === 0) return;
    const jobIds = jobs.map((j) => j.id);

    supabase
      .from("results")
      .select("job_id, overall_score")
      .in("job_id", jobIds)
      .then(({ data }) => {
        if (!data) return;
        const grouped: Record<string, number[]> = {};
        for (const row of data) {
          if (row.job_id && row.overall_score != null) {
            if (!grouped[row.job_id]) grouped[row.job_id] = [];
            grouped[row.job_id].push(row.overall_score);
          }
        }
        const averages: Record<string, number> = {};
        for (const [jobId, scores] of Object.entries(grouped)) {
          averages[jobId] = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
        }
        setAvgScores(averages);
      });
  }, [jobs]);

  // Reset page + selection when filters change
  useEffect(() => {
    setPage(1);
    setSelectedIds(new Set());
    setShowDeleteConfirm(false);
  }, [search, statusFilter, sortOption]);

  const filtered = useMemo(() => {
    let list = [...jobs];

    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter((j) => (j.title ?? "").toLowerCase().includes(q));
    }

    if (statusFilter !== "all") {
      list = list.filter((j) => j.status === statusFilter);
    }

    list.sort((a, b) => {
      switch (sortOption) {
        case "latest":
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
        case "oldest":
          return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
        case "name_asc":
          return (a.title ?? "").localeCompare(b.title ?? "");
        case "name_desc":
          return (b.title ?? "").localeCompare(a.title ?? "");
        case "resumes_desc":
          return b.resume_count - a.resume_count;
        case "score_desc": {
          const sa = avgScores[a.id] ?? -1;
          const sb = avgScores[b.id] ?? -1;
          return sb - sa;
        }
        default:
          return 0;
      }
    });

    return list;
  }, [jobs, search, statusFilter, sortOption, avgScores]);

  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paginated = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  const startIndex = filtered.length === 0 ? 0 : (page - 1) * PAGE_SIZE + 1;
  const endIndex = Math.min(page * PAGE_SIZE, filtered.length);

  // Bulk select helpers
  const pageIds = paginated.map((j) => j.id);
  const allPageSelected = pageIds.length > 0 && pageIds.every((id) => selectedIds.has(id));
  const somePageSelected = pageIds.some((id) => selectedIds.has(id));

  const toggleSelectAll = useCallback(() => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (allPageSelected) {
        pageIds.forEach((id) => next.delete(id));
      } else {
        pageIds.forEach((id) => next.add(id));
      }
      return next;
    });
    setShowDeleteConfirm(false);
  }, [allPageSelected, pageIds]);

  const toggleRow = useCallback((id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
    setShowDeleteConfirm(false);
  }, []);

  const clearSelection = useCallback(() => {
    setSelectedIds(new Set());
    setShowDeleteConfirm(false);
  }, []);

  const handleExportCSV = useCallback(() => {
    const selectedJobs = jobs.filter((j) => selectedIds.has(j.id));
    const header = ["Title", "Status", "Resumes", "Avg Score", "Created At"];
    const rows = selectedJobs.map((j) => [
      `"${(j.title ?? "Untitled Job").replace(/"/g, '""')}"`,
      j.status,
      j.resume_count,
      avgScores[j.id] != null ? `${avgScores[j.id]}%` : "—",
      format(new Date(j.created_at), "yyyy-MM-dd"),
    ]);
    const csv = [header.join(","), ...rows.map((r) => r.join(","))].join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `rankora-jobs-${format(new Date(), "yyyy-MM-dd")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success(`Exported ${selectedJobs.length} job${selectedJobs.length !== 1 ? "s" : ""}`);
  }, [jobs, selectedIds, avgScores]);

  const handleDeleteConfirmed = useCallback(async () => {
    if (!onDeleteJobs) return;
    setDeleting(true);
    try {
      await onDeleteJobs(Array.from(selectedIds));
      toast.success(`Deleted ${selectedIds.size} job${selectedIds.size !== 1 ? "s" : ""}`);
      setSelectedIds(new Set());
      setShowDeleteConfirm(false);
    } catch {
      toast.error("Failed to delete jobs. Please try again.");
    } finally {
      setDeleting(false);
    }
  }, [onDeleteJobs, selectedIds]);

  return (
    <Card className="w-full shadow-sm border border-border rounded-xl overflow-hidden">
      {/* ── Header ── */}
      <CardHeader className="px-6 pt-5 pb-4 border-b border-border">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1">
          <div>
            <CardTitle className="text-base font-semibold text-foreground">Jobs Overview</CardTitle>
            <p className="text-sm text-muted-foreground mt-0.5">
              Track and manage all your job postings.
            </p>
          </div>
          <span className="text-xs text-muted-foreground font-medium tabular-nums hidden sm:block">
            {filtered.length} job{filtered.length !== 1 ? "s" : ""}
          </span>
        </div>
      </CardHeader>

      <CardContent className="p-0">
        {/* ── Filter Bar ── */}
        <div className="flex flex-wrap items-center gap-2 px-6 py-3 border-b border-border bg-muted/20">
          {/* Search */}
          <div className="relative flex-1 min-w-[160px] max-w-[280px]">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
            <Input
              placeholder="Search jobs..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="h-8 pl-8 text-sm bg-background"
            />
          </div>

          {/* Status filter */}
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="h-8 w-[130px] text-sm bg-background">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="pending">Pending</SelectItem>
              <SelectItem value="processing">Processing</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
              <SelectItem value="failed">Failed</SelectItem>
            </SelectContent>
          </Select>

          {/* Sort */}
          <Select value={sortOption} onValueChange={(v) => setSortOption(v as SortOption)}>
            <SelectTrigger className="h-8 w-[150px] text-sm bg-background">
              <ArrowUpDown className="h-3.5 w-3.5 mr-1.5 text-muted-foreground" />
              <SelectValue placeholder="Sort" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="latest">Latest First</SelectItem>
              <SelectItem value="oldest">Oldest First</SelectItem>
              <SelectItem value="name_asc">Name A–Z</SelectItem>
              <SelectItem value="name_desc">Name Z–A</SelectItem>
              <SelectItem value="resumes_desc">Most Resumes</SelectItem>
              <SelectItem value="score_desc">Highest Score</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* ── Bulk Action Bar ── */}
        {selectedIds.size > 0 && !showDeleteConfirm && (
          <BulkActionBar
            count={selectedIds.size}
            onClear={clearSelection}
            onDelete={() => setShowDeleteConfirm(true)}
            onExport={handleExportCSV}
            deleting={deleting}
          />
        )}

        {/* ── Delete Confirm Banner ── */}
        {showDeleteConfirm && (
          <DeleteConfirmBanner
            count={selectedIds.size}
            onConfirm={handleDeleteConfirmed}
            onCancel={() => setShowDeleteConfirm(false)}
            deleting={deleting}
          />
        )}

        {/* ── Table ── */}
        <div className="overflow-x-auto">
          <table className="w-full text-sm table-fixed">
            <colgroup>
              <col className="w-10" />
              <col />
              <col className="w-20" />
              <col className="w-[120px]" />
              <col className="w-[110px]" />
              <col className="w-[110px]" />
              <col className="w-12" />
            </colgroup>
            <thead>
              <tr className="border-b border-border bg-muted/10">
                {/* Select All Checkbox */}
                <th className="pl-5 pr-2 py-2.5 w-10">
                  <Checkbox
                    checked={allPageSelected}
                    onCheckedChange={toggleSelectAll}
                    aria-label="Select all on this page"
                    className={cn(somePageSelected && !allPageSelected && "opacity-50")}
                  />
                </th>
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
                  Job Title
                </th>
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
                  Resumes
                </th>
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
                  Avg. Match Score
                </th>
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
                  Status
                </th>
                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
                  Created On
                </th>
                <th className="px-4 py-2.5" />
              </tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => <SkeletonRow key={i} />)
              ) : paginated.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-sm text-muted-foreground">
                    {search || statusFilter !== "all"
                      ? "No jobs match your filters."
                      : "No jobs yet. Create your first job to get started."}
                  </td>
                </tr>
              ) : (
                paginated.map((job, idx) => {
                  const globalIdx = (page - 1) * PAGE_SIZE + idx;
                  const { Icon, colorClass } = getJobIconProps(job.title, globalIdx);
                  const tags = extractEmploymentTags(job.jd_analysis_json);
                  const avgScore = job.resume_count > 0 ? (avgScores[job.id] ?? null) : null;
                  const isSelected = selectedIds.has(job.id);

                  return (
                    <tr
                      key={job.id}
                      className={cn(
                        "border-b border-border last:border-0 hover:bg-muted/30 cursor-pointer transition-colors group",
                        isSelected && "bg-primary/[0.04]"
                      )}
                      onClick={() => onSelectJob(job.id)}
                    >
                      {/* Checkbox */}
                      <td className="pl-5 pr-2 py-3.5" onClick={(e) => toggleRow(job.id, e)}>
                        <Checkbox
                          checked={isSelected}
                          onCheckedChange={() => {}}
                          aria-label={`Select ${job.title ?? "job"}`}
                          className="pointer-events-none"
                        />
                      </td>

                      {/* Job Title */}
                      <td className="px-4 py-3.5">
                        <div className="flex items-center gap-3 min-w-0">
                          <div
                            className={cn(
                              "h-9 w-9 rounded-lg flex items-center justify-center shrink-0",
                              colorClass
                            )}
                          >
                            <Icon className="h-4 w-4" />
                          </div>
                          <div className="min-w-0">
                            <p className="font-medium text-foreground truncate max-w-[220px]">
                              {job.title || "Untitled Job"}
                            </p>
                            {tags.length > 0 && (
                              <p className="text-xs text-muted-foreground mt-0.5 truncate">
                                {tags.join(" · ")}
                              </p>
                            )}
                          </div>
                        </div>
                      </td>

                      {/* Resumes */}
                      <td className="px-4 py-3.5">
                        <span className="font-medium tabular-nums text-foreground">
                          {job.resume_count}
                        </span>
                      </td>

                      {/* Avg Match Score */}
                      <td className="px-4 py-3.5">
                        <CircularScore score={avgScore} />
                      </td>

                      {/* Status */}
                      <td className="px-4 py-3.5">
                        <StatusBadge status={job.status} />
                      </td>

                      {/* Created On */}
                      <td className="px-4 py-3.5 whitespace-nowrap text-muted-foreground text-xs">
                        {format(new Date(job.created_at), "MMM d, yyyy")}
                      </td>

                      {/* Arrow */}
                      <td className="px-4 py-3.5">
                        <ChevronRight className="h-4 w-4 text-muted-foreground group-hover:text-foreground transition-colors" />
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {/* ── Pagination ── */}
        {loading ? (
          <div className="flex items-center justify-between px-6 py-3 border-t border-border bg-muted/10">
            <Skeleton className="h-3.5 w-32 rounded" />
            <div className="flex items-center gap-1">
              <Skeleton className="h-7 w-12 rounded" />
              <Skeleton className="h-7 w-7 rounded" />
              <Skeleton className="h-7 w-7 rounded" />
              <Skeleton className="h-7 w-12 rounded" />
            </div>
          </div>
        ) : filtered.length > 0 ? (
          <div className="flex flex-col sm:flex-row items-center justify-between gap-3 px-6 py-3 border-t border-border bg-muted/10">
            <p className="text-xs text-muted-foreground">
              Showing {startIndex}–{endIndex} of {filtered.length} job{filtered.length !== 1 ? "s" : ""}
            </p>

            {totalPages > 1 && (
              <div className="flex items-center gap-1">
                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 px-2.5 text-xs"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page === 1}
                >
                  Prev
                </Button>

                {Array.from({ length: totalPages }).map((_, i) => {
                  const pageNum = i + 1;
                  const nearCurrent = Math.abs(pageNum - page) <= 1;
                  const isFirst = pageNum === 1;
                  const isLast = pageNum === totalPages;
                  if (!nearCurrent && !isFirst && !isLast) {
                    if (pageNum === 2 && page > 3) return <span key={pageNum} className="text-xs text-muted-foreground px-1">…</span>;
                    if (pageNum === totalPages - 1 && page < totalPages - 2) return <span key={pageNum} className="text-xs text-muted-foreground px-1">…</span>;
                    return null;
                  }
                  return (
                    <Button
                      key={pageNum}
                      variant={page === pageNum ? "default" : "outline"}
                      size="sm"
                      className="h-7 w-7 p-0 text-xs"
                      onClick={() => setPage(pageNum)}
                    >
                      {pageNum}
                    </Button>
                  );
                })}

                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 px-2.5 text-xs"
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  disabled={page === totalPages}
                >
                  Next
                </Button>
              </div>
            )}
          </div>
        ) : null}
      </CardContent>
    </Card>
  );
};

// ─── Status Badge ─────────────────────────────────────────────────────────────

function StatusBadge({ status }: { status: string }) {
  switch (status) {
    case "completed":
      return <Badge variant="success" className="capitalize text-xs font-medium">Completed</Badge>;
    case "processing":
      return <Badge variant="warning" className="capitalize text-xs font-medium">Processing</Badge>;
    case "pending":
      return <Badge variant="warning" className="capitalize text-xs font-medium">Pending</Badge>;
    case "failed":
      return <Badge variant="destructive" className="capitalize text-xs font-medium">Failed</Badge>;
    default:
      return <Badge variant="outline" className="capitalize text-xs font-medium">{status}</Badge>;
  }
}

