import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "sonner";
import {
  Brain,
  Mail,
  CreditCard,
  MessageCircle,
  Sparkles,
  CheckCircle2,
  XCircle,
  Loader2,
  ChevronDown,
  RefreshCw,
  ExternalLink,
  Plug,
} from "lucide-react";
import { cn } from "@/lib/utils";

// ─── Status Badge ────────────────────────────────────────────────────────────

const StatusDot = ({ status }: { status: string | null }) => {
  if (status === "success")
    return (
      <Badge className="gap-1 bg-emerald-50 hover:bg-emerald-50 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800 text-xs shrink-0">
        <CheckCircle2 className="h-3 w-3" />
        Connected
      </Badge>
    );
  if (status === "failed")
    return (
      <Badge variant="destructive" className="gap-1 text-xs shrink-0">
        <XCircle className="h-3 w-3" />
        Failed
      </Badge>
    );
  return (
    <Badge variant="secondary" className="text-xs shrink-0">
      Not tested
    </Badge>
  );
};

// ─── Integration Card ────────────────────────────────────────────────────────

interface IntegrationCardProps {
  icon: React.ReactNode;
  name: string;
  description: string;
  status: string | null;
  lastTested: string | null;
  keyName: string;
  testing: string | null;
  onTest: (keyName: string) => void;
  docsUrl?: string;
}

const IntegrationCard = ({
  icon,
  name,
  description,
  status,
  lastTested,
  keyName,
  testing,
  onTest,
  docsUrl,
}: IntegrationCardProps) => {
  const [open, setOpen] = useState(false);
  const isTesting = testing === keyName;

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <Card className="border border-border/60 shadow-sm overflow-hidden">
        <CollapsibleTrigger asChild>
          <button className="w-full flex items-center gap-4 px-5 py-4 text-left hover:bg-muted/30 transition-colors">
            <div className="h-10 w-10 rounded-lg bg-muted/60 flex items-center justify-center shrink-0">
              {icon}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-foreground">{name}</p>
              <p className="text-xs text-muted-foreground mt-0.5 truncate">
                {description}
              </p>
            </div>
            <StatusDot status={status} />
            <ChevronDown
              className={cn(
                "h-4 w-4 text-muted-foreground shrink-0 transition-transform duration-200",
                open && "rotate-180"
              )}
            />
          </button>
        </CollapsibleTrigger>

        <CollapsibleContent>
          <div className="px-5 pb-4 pt-1 border-t border-border/40 space-y-3">
            {/* Status & last tested */}
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <span>
                Last tested:{" "}
                {lastTested
                  ? new Date(lastTested).toLocaleString()
                  : "Never"}
              </span>
              <div className="flex items-center gap-2">
                {docsUrl && (
                  <a
                    href={docsUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-xs text-primary hover:underline"
                  >
                    Docs <ExternalLink className="h-3 w-3" />
                  </a>
                )}
                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 text-xs gap-1.5"
                  onClick={(e) => {
                    e.stopPropagation();
                    onTest(keyName);
                  }}
                  disabled={isTesting}
                >
                  {isTesting ? (
                    <Loader2 className="h-3 w-3 animate-spin" />
                  ) : (
                    <RefreshCw className="h-3 w-3" />
                  )}
                  Test Connection
                </Button>
              </div>
            </div>

            {/* Secret info */}
            <div className="rounded-lg bg-muted/40 p-3">
              <p className="text-xs text-muted-foreground">
                This integration is configured via environment secrets in your Supabase project.
                Contact your admin to update the API key.
              </p>
              <div className="mt-2 flex items-center gap-2">
                <code className="text-[11px] bg-background px-1.5 py-0.5 rounded font-mono border border-border/60">
                  {keyName}
                </code>
                <Badge variant="outline" className="text-[10px] shrink-0">
                  Env Secret
                </Badge>
              </div>
            </div>
          </div>
        </CollapsibleContent>
      </Card>
    </Collapsible>
  );
};

// ─── Loading Skeleton ────────────────────────────────────────────────────────

const IntegrationSkeleton = () => (
  <div className="space-y-3">
    {Array.from({ length: 5 }).map((_, i) => (
      <Card key={i} className="border border-border/60 shadow-sm">
        <div className="flex items-center gap-4 px-5 py-4">
          <Skeleton className="h-10 w-10 rounded-lg" />
          <div className="flex-1 space-y-2">
            <Skeleton className="h-4 w-32 rounded" />
            <Skeleton className="h-3 w-48 rounded" />
          </div>
          <Skeleton className="h-5 w-20 rounded-full" />
        </div>
      </Card>
    ))}
  </div>
);

// ─── Integration definitions ─────────────────────────────────────────────────

const INTEGRATIONS = [
  {
    keyName: "OPENAI_API_KEY",
    name: "OpenAI",
    description: "GPT-4o for resume analysis, JD parsing, and scoring",
    icon: <Brain className="h-5 w-5 text-emerald-600" />,
    docsUrl: "https://platform.openai.com/docs",
  },
  {
    keyName: "GEMINI_API_KEY",
    name: "Google Gemini",
    description: "Alternative AI model for resume analysis",
    icon: <Sparkles className="h-5 w-5 text-blue-500" />,
    docsUrl: "https://ai.google.dev/docs",
  },
  {
    keyName: "RESEND_API_KEY",
    name: "Resend",
    description: "Transactional emails, notifications, and inbound resume ingestion",
    icon: <Mail className="h-5 w-5 text-violet-500" />,
    docsUrl: "https://resend.com/docs",
  },
  {
    keyName: "DODO_PAYMENTS_API_KEY",
    name: "Dodo Payments",
    description: "Subscriptions, credit packs, and hosted checkout",
    icon: <CreditCard className="h-5 w-5 text-orange-500" />,
    docsUrl: "https://docs.dodopayments.com",
  },
  {
    keyName: "CHAT_WIDGET",
    name: "Chat Widget",
    description: "Live chat support widget (Intercom, Crisp, Tawk.to, etc.)",
    icon: <MessageCircle className="h-5 w-5 text-sky-500" />,
  },
];

// ─── Main Page ───────────────────────────────────────────────────────────────

const Integrations = () => {
  const { isAdmin } = useAuth();
  const qc = useQueryClient();
  const [testing, setTesting] = useState<string | null>(null);

  const { data: integrations, isLoading } = useQuery({
    queryKey: ["integrations_status"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("integrations")
        .select("*")
        .order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const testIntegration = async (keyName: string) => {
    if (!isAdmin) {
      toast.error("Only admins can test integrations");
      return;
    }
    setTesting(keyName);
    try {
      const { data, error } = await supabase.functions.invoke(
        "admin-test-integration",
        { body: { key_name: keyName } }
      );
      if (error) throw error;
      if (data.status === "success") {
        toast.success("Connection successful!");
      } else {
        toast.error(data.error || "Connection test failed");
      }
      qc.invalidateQueries({ queryKey: ["integrations_status"] });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setTesting(null);
    }
  };

  const getIntegration = (key: string) =>
    integrations?.find((i: any) => i.key_name === key);

  return (
    <SidebarLayout>
      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex items-center justify-between mb-1">
          <h1 className="text-2xl font-bold text-foreground">Integrations</h1>
          <Badge variant="secondary" className="text-xs gap-1">
            <Plug className="h-3 w-3" />
            {integrations?.filter((i: any) => i.last_test_status === "success")
              .length ?? 0}{" "}
            / {INTEGRATIONS.length} connected
          </Badge>
        </div>
        <p className="text-sm text-muted-foreground mb-6">
          View and test your connected services. Click any integration to see
          details.
        </p>

        {isLoading ? (
          <IntegrationSkeleton />
        ) : (
          <div className="space-y-3">
            {INTEGRATIONS.map((integ) => {
              const data = getIntegration(integ.keyName);
              return (
                <IntegrationCard
                  key={integ.keyName}
                  icon={integ.icon}
                  name={integ.name}
                  description={integ.description}
                  status={data?.last_test_status ?? null}
                  lastTested={data?.last_tested_at ?? null}
                  keyName={integ.keyName}
                  testing={testing}
                  onTest={testIntegration}
                  docsUrl={integ.docsUrl}
                />
              );
            })}
          </div>
        )}
      </main>
    </SidebarLayout>
  );
};

export default Integrations;

