const INTEGRATIONS = [
  {
    keyName: "OPENAI_API_KEY",
    name: "OpenAI",
    description: "GPT-4o for resume analysis, JD parsing, and scoring",
    icon: <Brain className="h-5 w-5 text-emerald-600" />,
    docsUrl: "https://platform.openai.com/docs",
  },
  {
    keyName: "GEMINI_API_KEY",
    name: "Google Gemini",
    description: "Alternative AI model for resume analysis",
    icon: <Sparkles className="h-5 w-5 text-blue-500" />,
    docsUrl: "https://ai.google.dev/docs",
  },
  {
    keyName: "RESEND_API_KEY",
    name: "Resend",
    description: "Transactional emails, notifications, and inbound resume ingestion",
    icon: <Mail className="h-5 w-5 text-violet-500" />,
    docsUrl: "https://resend.com/docs",
  },
  {
    keyName: "DODO_PAYMENTS_API_KEY",
    name: "Dodo Payments",
    description: "Subscriptions, credit packs, and hosted checkout",
    icon: <CreditCard className="h-5 w-5 text-orange-500" />,
    docsUrl: "https://docs.dodopayments.com",
  },
  {
    keyName: "CHAT_WIDGET",
    name: "Chat Widget",
    description: "Live chat support widget (Intercom, Crisp, Tawk.to, etc.)",
    icon: <MessageCircle className="h-5 w-5 text-sky-500" />,
  },
];

