const Integrations = () => {
  const { isAdmin } = useAuth();
  const qc = useQueryClient();
  const [testing, setTesting] = useState<string | null>(null);

  const { data: integrations, isLoading } = useQuery({
    queryKey: ["integrations_status"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("integrations")
        .select("*")
        .order("created_at");
      if (error) throw error;
      return data;
    },
  });

  const testIntegration = async (keyName: string) => {
    if (!isAdmin) {
      toast.error("Only admins can test integrations");
      return;
    }
    setTesting(keyName);
    try {
      const { data, error } = await supabase.functions.invoke(
        "admin-test-integration",
        { body: { key_name: keyName } }
      );
      if (error) throw error;
      if (data.status === "success") {
        toast.success("Connection successful!");
      } else {
        toast.error(data.error || "Connection test failed");
      }
      qc.invalidateQueries({ queryKey: ["integrations_status"] });
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setTesting(null);
    }
  };

  const getIntegration = (key: string) =>
    integrations?.find((i: any) => i.key_name === key);

  return (
    <SidebarLayout>
      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
