        </div>
        <p className="text-sm text-muted-foreground mb-6">
          View and test your connected services. Click any integration to see
          details.
        </p>

        {isLoading ? (
          <IntegrationSkeleton />
        ) : (
          <div className="space-y-3">
            {INTEGRATIONS.map((integ) => {
              const data = getIntegration(integ.keyName);
              return (
                <IntegrationCard
                  key={integ.keyName}
                  icon={integ.icon}
                  name={integ.name}
                  description={integ.description}
                  status={data?.last_test_status ?? null}
                  lastTested={data?.last_tested_at ?? null}
                  keyName={integ.keyName}
                  testing={testing}
                  onTest={testIntegration}
                  docsUrl={integ.docsUrl}
                />
              );
            })}
          </div>
        )}
      </main>
    </SidebarLayout>
  );
};

export default Integrations;

