import {
  Briefcase,
  Home,
  Settings,
  CreditCard,
  Users,
  CheckSquare,
  Activity,
  Globe,
  Layers,
  Megaphone,
  FileText,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
} from "@/components/ui/sidebar";
import { useNavigate, useLocation, Link } from "react-router-dom";
import { cn } from "@/lib/utils";

interface JobSidebarProps {
  showDashboard?: boolean;
  showMyJobs?: boolean;
  onNewJob?: () => void;
  onDashboard?: () => void;
  onMyJobs?: () => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
  selectedJobId?: string | null;
}

const JobSidebar = ({
  showDashboard,
  showMyJobs,
  onDashboard,
  onMyJobs,
  isAuthenticated = true,
}: JobSidebarProps) => {
  const navigate = useNavigate();
  const { pathname } = useLocation();

  const mainNav = [
    {
      icon: Home,
      label: "Dashboard",
      isActive: !!showDashboard,
      onClick: onDashboard,
      show: isAuthenticated && !!onDashboard,
    },
    {
      icon: Briefcase,
      label: "My Jobs",
      isActive: !!showMyJobs,
      onClick: onMyJobs,
      show: isAuthenticated && !!onMyJobs,
    },
    {
      icon: CheckSquare,
      label: "Tasks",
      isActive: pathname === "/tasks",
      onClick: () => navigate("/tasks"),
      show: isAuthenticated,
    },
    {
      icon: Activity,
      label: "Activity",
      isActive: pathname === "/activity",
      onClick: () => navigate("/activity"),
      show: isAuthenticated,
    },
  ];

  const settingsNav = [
    {
      icon: CreditCard,
      label: "Billing",
      isActive: pathname === "/billing",
      onClick: () => navigate("/billing"),
    },
    {
      icon: Users,
      label: "Team",
      isActive: pathname === "/team",
      onClick: () => navigate("/team"),
    },
    {
      icon: Globe,
      label: "Career Page",
      isActive: pathname === "/career-settings",
      onClick: () => navigate("/career-settings"),
    },
    {
      icon: Settings,
      label: "Settings",
      isActive: pathname === "/settings",
      onClick: () => navigate("/settings"),
    },
  ];

  return (
    <Sidebar collapsible="offcanvas" className="border-r border-border/60 bg-sidebar">
      {/* ── Brand ── */}
