import {
  Briefcase,
  Home,
  Settings,
  CreditCard,
  Users,
  CheckSquare,
  Activity,
  Globe,
  Layers,
  Megaphone,
  FileText,
  Plug,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
} from "@/components/ui/sidebar";
import { useNavigate, useLocation, Link } from "react-router-dom";
import { cn } from "@/lib/utils";

interface JobSidebarProps {
  showDashboard?: boolean;
  showMyJobs?: boolean;
  onNewJob?: () => void;
  onDashboard?: () => void;
  onMyJobs?: () => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
  selectedJobId?: string | null;
}

const JobSidebar = ({
  showDashboard,
  showMyJobs,
  onDashboard,
  onMyJobs,
  isAuthenticated = true,
}: JobSidebarProps) => {
  const navigate = useNavigate();
  const { pathname } = useLocation();

  const mainNav = [
    {
      icon: Home,
      label: "Dashboard",
      isActive: !!showDashboard,
      onClick: onDashboard,
      show: isAuthenticated && !!onDashboard,
    },
    {
      icon: Briefcase,
      label: "My Jobs",
      isActive: !!showMyJobs,
      onClick: onMyJobs,
      show: isAuthenticated && !!onMyJobs,
    },
    {
      icon: CheckSquare,
      label: "Tasks",
      isActive: pathname === "/tasks",
      onClick: () => navigate("/tasks"),
      show: isAuthenticated,
    },
    {
      icon: Activity,
      label: "Activity",
      isActive: pathname === "/activity",
      onClick: () => navigate("/activity"),
      show: isAuthenticated,
    },
  ];

  const settingsNav = [
    {
      icon: CreditCard,
      label: "Billing",
      isActive: pathname === "/billing",
      onClick: () => navigate("/billing"),
    },
    {
      icon: Users,
      label: "Team",
      isActive: pathname === "/team",
      onClick: () => navigate("/team"),
    },
    {
      icon: Globe,
      label: "Career Page",
      isActive: pathname === "/career-settings",
      onClick: () => navigate("/career-settings"),
    },
    {
      icon: Settings,
      label: "Settings",
      isActive: pathname === "/settings",
      onClick: () => navigate("/settings"),
    },
  ];

  return (
    <Sidebar collapsible="offcanvas" className="border-r border-border/60 bg-sidebar">
      {/* ── Brand ── */}
      <SidebarHeader className="px-3 py-3.5 border-b border-border/40">
        <button
          onClick={onDashboard}
          className="flex items-center gap-2.5 px-1.5 py-1 rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring w-full text-left hover:bg-sidebar-accent/60 transition-colors duration-150"
        >
          <div className="h-6 w-6 rounded-md bg-primary flex items-center justify-center shrink-0">
            <Layers className="h-3.5 w-3.5 text-primary-foreground" />
          </div>
          <span className="font-semibold text-sm text-foreground tracking-tight">
            Rankora
          </span>
        </button>
      </SidebarHeader>

      {/* ── Nav ── */}
      <SidebarContent className="px-2 py-3">

        {/* Main */}
        <div className="mb-4">
          <p className="px-2 mb-1 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/50 select-none">
            Main
          </p>
          <SidebarMenu>
            {mainNav.filter((i) => i.show).map(({ icon: Icon, label, isActive, onClick }) => (
              <SidebarMenuItem key={label}>
                <SidebarMenuButton
                  isActive={isActive}
                  onClick={onClick}
                  className={cn(
                    "h-8 gap-2.5 rounded-md text-[13px] font-medium transition-colors duration-100",
                    isActive
                      ? "bg-sidebar-accent text-sidebar-accent-foreground"
                      : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
                  )}
                >
                  <Icon className={cn("h-[15px] w-[15px] shrink-0", isActive ? "text-foreground" : "text-muted-foreground")} />
                  <span>{label}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            ))}
          </SidebarMenu>
        </div>

        {/* Settings */}
        {isAuthenticated && (
          <div>
            <p className="px-2 mb-1 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/50 select-none">
              Settings
            </p>
            <SidebarMenu>
              {settingsNav.map(({ icon: Icon, label, isActive, onClick }) => (
                <SidebarMenuItem key={label}>
                  <SidebarMenuButton
                    isActive={isActive}
                    onClick={onClick}
                    className={cn(
                      "h-8 gap-2.5 rounded-md text-[13px] font-medium transition-colors duration-100",
                      isActive
                        ? "bg-sidebar-accent text-sidebar-accent-foreground"
                        : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
                    )}
                  >
                    <Icon className={cn("h-[15px] w-[15px] shrink-0", isActive ? "text-foreground" : "text-muted-foreground")} />
                    <span>{label}</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </div>
        )}
      </SidebarContent>

      {/* ── Footer ── */}
      <SidebarFooter className="px-2 pb-3 pt-1">
        <div className="border-t border-border/40 pt-3 space-y-0.5">
          <Link
            to="/request-feature"
            className={cn(
              "flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100",
              pathname === "/request-feature"
                ? "bg-sidebar-accent text-foreground"
                : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
            )}
          >
            <Megaphone className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
            <span>Feature Request</span>
          </Link>
          <Link
            to="/changelog"
            className={cn(
              "flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100",
              pathname === "/changelog"
                ? "bg-sidebar-accent text-foreground"
                : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
            )}
          >
            <FileText className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
            <span>Changelog</span>
          </Link>
        </div>
      </SidebarFooter>
    </Sidebar>
  );
};

export default JobSidebar;

