import SidebarLayout from "@/components/SidebarLayout";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import {
  Linkedin,
  MessageSquare,
  CalendarDays,
  Zap,
  FileSearch,
  Mail,
  Users,
  Building2,
  Briefcase,
} from "lucide-react";
import { cn } from "@/lib/utils";

// ─── Types ───────────────────────────────────────────────────────────────────

interface Integration {
  id: string;
  name: string;
  description: string;
  icon: React.ReactNode;
  iconBg: string;
  status: "available" | "connected" | "coming_soon";
}

// ─── Integration definitions ─────────────────────────────────────────────────

const INTEGRATIONS: Integration[] = [
  {
    id: "linkedin",
    name: "LinkedIn",
    description: "Import candidates and post jobs directly to LinkedIn.",
    icon: <Linkedin className="h-5 w-5 text-[#0A66C2]" />,
    iconBg: "bg-[#0A66C2]/10",
    status: "available",
  },
  {
    id: "slack",
    name: "Slack",
    description: "Get notifications for new applications and rankings.",
    icon: <MessageSquare className="h-5 w-5 text-[#4A154B]" />,
    iconBg: "bg-[#4A154B]/10",
    status: "available",
  },
  {
    id: "google-calendar",
    name: "Google Calendar",
    description: "Schedule interviews and sync availability with candidates.",
    icon: <CalendarDays className="h-5 w-5 text-[#4285F4]" />,
    iconBg: "bg-[#4285F4]/10",
    status: "available",
  },
  {
    id: "zapier",
    name: "Zapier",
    description: "Connect with 5,000+ apps via powerful automations.",
    icon: <Zap className="h-5 w-5 text-[#FF4A00]" />,
    iconBg: "bg-[#FF4A00]/10",
    status: "available",
  },
  {
    id: "indeed",
    name: "Indeed",
    description: "Import resumes directly from Indeed job postings.",
    icon: <FileSearch className="h-5 w-5 text-[#2164F3]" />,
    iconBg: "bg-[#2164F3]/10",
    status: "available",
  },
  {
    id: "google-workspace",
    name: "Google Workspace",
    description: "Sync with Gmail, Google Drive, and Contacts.",
    icon: <Mail className="h-5 w-5 text-[#EA4335]" />,
    iconBg: "bg-[#EA4335]/10",
    status: "available",
  },
  {
    id: "ms-teams",
    name: "Microsoft Teams",
    description: "Team notifications and collaboration for hiring.",
    icon: <Users className="h-5 w-5 text-[#6264A7]" />,
    iconBg: "bg-[#6264A7]/10",
    status: "coming_soon",
  },
  {
    id: "greenhouse",
    name: "Greenhouse",
    description: "Sync candidates with your Greenhouse ATS pipeline.",
    icon: <Building2 className="h-5 w-5 text-[#24A47F]" />,
    iconBg: "bg-[#24A47F]/10",
    status: "coming_soon",
  },
  {
    id: "workday",
    name: "Workday",
    description: "Enterprise HR system integration for large teams.",
    icon: <Briefcase className="h-5 w-5 text-[#005CB9]" />,
    iconBg: "bg-[#005CB9]/10",
    status: "coming_soon",
  },
];

// ─── Integration Card ────────────────────────────────────────────────────────

const IntegrationCard = ({ integration }: { integration: Integration }) => {
  const isSoon = integration.status === "coming_soon";
  const isConnected = integration.status === "connected";

  const handleConnect = () => {
    toast.info(`${integration.name} integration coming soon!`);
  };

  return (
    <Card
      className={cn(
        "relative border border-border/60 shadow-sm hover:shadow-md transition-shadow p-5",
        isSoon && "opacity-50 pointer-events-none"
      )}
    >
      {/* Badge */}
      {isSoon && (
        <Badge
          variant="secondary"
          className="absolute top-4 right-4 text-[10px] font-semibold"
        >
          Soon
        </Badge>
      )}
      {isConnected && (
        <Badge className="absolute top-4 right-4 text-[10px] font-semibold bg-emerald-50 text-emerald-700 hover:bg-emerald-50 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-800">
          Connected
        </Badge>
      )}

      {/* Icon */}
      <div
        className={cn(
          "h-10 w-10 rounded-xl flex items-center justify-center mb-3.5",
          integration.iconBg
        )}
      >
        {integration.icon}
      </div>

      {/* Text */}
      <p className="text-sm font-semibold text-foreground">{integration.name}</p>
      <p className="text-xs text-muted-foreground mt-1 leading-relaxed">
        {integration.description}
      </p>

      {/* Action */}
      {!isSoon && !isConnected && (
        <Button
          variant="outline"
          size="sm"
          className="mt-4 h-8 text-xs w-full"
          onClick={handleConnect}
        >
          Connect
        </Button>
      )}
      {isConnected && (
        <Button
          variant="ghost"
          size="sm"
          className="mt-4 h-8 text-xs w-full text-muted-foreground"
          onClick={handleConnect}
        >
          Manage
        </Button>
      )}
    </Card>
  );
};

// ─── Main Page ───────────────────────────────────────────────────────────────

const Integrations = () => {
  const available = INTEGRATIONS.filter((i) => i.status !== "coming_soon");
  const comingSoon = INTEGRATIONS.filter((i) => i.status === "coming_soon");

  return (
    <SidebarLayout>
      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <h1 className="text-2xl font-bold text-foreground mb-1">
          Integrations
        </h1>
        <p className="text-sm text-muted-foreground mb-6">
          Connect your favorite tools to streamline your hiring workflow.
        </p>

        {/* Available */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {available.map((integ) => (
            <IntegrationCard key={integ.id} integration={integ} />
          ))}
        </div>

        {/* Coming Soon */}
        {comingSoon.length > 0 && (
          <>
            <h2 className="text-sm font-semibold text-muted-foreground mt-10 mb-4">
              Coming Soon
            </h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {comingSoon.map((integ) => (
                <IntegrationCard key={integ.id} integration={integ} />
              ))}
            </div>
          </>
        )}
      </main>
    </SidebarLayout>
  );
};

export default Integrations;

