import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

interface SendCandidateEmailRequest {
  resume_id: string;
  job_id: string;
  to_email: string;
  subject: string;
  body_html: string;
}

/** Send an email via Resend API */
async function sendViaResend(
  apiKey: string,
  from: { email: string; name: string },
  to: string,
  subject: string,
  htmlContent: string
): Promise<{ ok: boolean; status: number; body: string; errorMessage?: string }> {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: `${from.name} <${from.email}>`,
      to: [to],
      subject,
      html: htmlContent,
    }),
  });

  const body = await res.text();
  let errorMessage: string | undefined;

  if (!res.ok) {
    try {
      const parsed = JSON.parse(body);
      errorMessage = parsed.message || parsed.error?.message;
    } catch { /* ignore */ }
  }

  return { ok: res.ok, status: res.status, body, errorMessage };
}

serve(async (req) => {
  const corsHeaders = {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  };
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Verify JWT
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) {
    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const token = authHeader.replace("Bearer ", "");
  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
  if (authError || !user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  try {
    const { resume_id, job_id, to_email, subject, body_html } =
      (await req.json()) as SendCandidateEmailRequest;

    if (!resume_id || !job_id || !to_email || !subject || !body_html) {
      return new Response(
        JSON.stringify({ error: "Missing required fields: resume_id, job_id, to_email, subject, body_html" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Load platform config for Resend credentials
    const { data: config, error: configError } = await supabase
      .from("platform_config")
      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled")
      .limit(1)
      .single();

    if (configError) throw new Error(`Config error: ${configError.message}`);

    if (!config?.outbound_email_enabled) {
      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!config.resend_api_key) {
      return new Response(JSON.stringify({ error: "Resend API key not configured" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const fromEmail = config.email_from_address || "noreply@rankora.co";
    const fromName = config.email_from_name || "Rankora";

    // Send via Resend
    const result = await sendViaResend(
      config.resend_api_key,
      { email: fromEmail, name: fromName },
      to_email,
      subject,
      body_html
    );

    const logStatus = result.ok ? "sent" : "failed";

    // Log to outreach_log regardless of send result
    const { error: logError } = await supabase.from("outreach_log").insert({
      resume_id,
      job_id,
      type: "email",
      to_address: to_email,
      subject,
      status: logStatus,
      user_id: user.id,
    });

    if (logError) {
      console.error("Failed to log outreach:", logError.message);
      await logSystemError({
        function_name: "send-candidate-email",
        error_type: "OUTREACH_LOG_ERROR",
        severity: "warning",
        error_message: `Failed to log outreach: ${logError.message}`,
        user_id: user.id,
        job_id,
      });
    }

    if (!result.ok) {
      const errorMessage = result.errorMessage || `Resend error (status ${result.status})`;

      console.error("Resend error:", result.status, result.body);
      await logSystemError({
        function_name: "send-candidate-email",
        error_type: "RESEND_SEND_ERROR",
        severity: "warning",
        error_message: `Resend error: status=${result.status} body=${result.body}`,
        user_id: user.id,
        job_id,
      });
      return new Response(
        JSON.stringify({ error: errorMessage }),
        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    console.error("send-candidate-email error:", err);
    await logSystemError({
      function_name: "send-candidate-email",
      error_type: "EMAIL_SEND_ERROR",
      severity: "warning",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

