import { Fragment } from "react";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import { XCircle } from "lucide-react";
import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
import { format } from "date-fns";

interface CustomStage {
  name: string;
  color: string;
}

interface StageTrackerProps {
  currentStage: string;
  updatedAt?: string | null;
  onStageChange: (stage: HiringStage) => void;
  disabled?: boolean;
  /** Optional custom stages — when provided renders them instead of hardcoded STAGE_ORDER */
  customStages?: CustomStage[];
}

const STAGE_LABELS: Record<string, string> = {
  applied: "Applied",
  screened: "Screened",
  interview: "Interview",
  offer: "Offer",
  hired: "Hired",
};

const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled, customStages }: StageTrackerProps) => {
  // When customStages provided, derive stage order from them; otherwise use hardcoded STAGE_ORDER
  const effectiveStages: string[] = customStages
    ? customStages.map((s) => s.name.toLowerCase())
    : STAGE_ORDER;

  const effectiveLabels: Record<string, string> = customStages
    ? Object.fromEntries(customStages.map((s) => [s.name.toLowerCase(), s.name]))
    : STAGE_LABELS;

  const normalizedCurrent = currentStage.toLowerCase();
  const currentIndex = normalizedCurrent === "rejected" ? -1 : effectiveStages.indexOf(normalizedCurrent);
  const isRejected = normalizedCurrent === "rejected";

  return (
    <div className="flex items-center gap-3 py-1">
      <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>

      {/* Dots + connectors + labels */}

