import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { Loader2, Mail, Sparkles, UserX, ExternalLink } from "lucide-react";
import type { Result } from "@/pages/Index";
import type { HiringStage } from "@/hooks/useStageTracker";

interface RejectCandidateDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  result: Result;
  jobTitle: string;
  jobId: string;
  onStageChange?: (resumeId: string, stage: HiringStage) => void;
}

function buildRejectionEmail(
  candidateName: string,
  jobTitle: string,
  result: Result
): string {
  const name = candidateName || "Candidate";
  const gaps = result.gaps_json ?? [];
  const missingSkills = result.missing_skills ?? [];
  const missingMust = result.missing_must_haves ?? [];
  const strengths = result.strengths_json ?? [];

  let feedback = "";

  // Personalized strengths acknowledgment
  if (strengths.length > 0) {
    const topStrengths = strengths.slice(0, 2).join(" and ");
    feedback += `We were particularly impressed by your ${topStrengths.toLowerCase()}. `;
  }

  // Specific feedback on gaps
  const allGaps = [...new Set([...gaps, ...missingSkills, ...missingMust])];
  if (allGaps.length > 0) {
    const topGaps = allGaps.slice(0, 3);
    feedback += `After careful review, we found that this role requires stronger alignment in areas such as ${topGaps.join(", ").toLowerCase()}, which were key requirements for the position.`;
  } else {
    feedback += "After careful consideration, we've decided to move forward with candidates whose experience more closely matches the specific requirements of this role.";
  }

  return `Hi ${name},

Thank you for taking the time to apply for the ${jobTitle} position. We appreciate your interest and the effort you put into your application.

${feedback}

We encourage you to apply for future roles that match your skill set — we'd love to stay connected for opportunities that may be a better fit.

Wishing you the best in your career journey.

Best regards`;
}

function buildSubject(jobTitle: string): string {
  return `Update on Your Application — ${jobTitle}`;
}

const RejectCandidateDialog = ({
  open,
  onOpenChange,
  result,
  jobTitle,
  jobId,
  onStageChange,
}: RejectCandidateDialogProps) => {
  const candidateName = result.candidate_name || "Candidate";
  const candidateEmail = result.candidate_email || "";

  const [subject, setSubject] = useState("");
  const [bodyText, setBodyText] = useState("");
  const [isSending, setIsSending] = useState(false);

  // Generate email content when dialog opens
  useEffect(() => {
    if (open) {
      setSubject(buildSubject(jobTitle));
      setBodyText(buildRejectionEmail(candidateName, jobTitle, result));
    }
  }, [open, candidateName, jobTitle, result]);

  const handleSendAndReject = async () => {
    if (!candidateEmail) {
      // No email — just change stage
      if (onStageChange) {
        onStageChange(result.resume_id, "rejected" as HiringStage);
      }
      toast.success(`${candidateName} moved to Rejected`);
      onOpenChange(false);
      return;
    }

    if (!subject.trim() || !bodyText.trim()) {
      toast.error("Subject and message are required");
      return;
    }

    setIsSending(true);
    try {
      const bodyHtml = bodyText.replace(/\n/g, "<br>");
      const { data, error } = await supabase.functions.invoke("send-candidate-email", {
        body: {
          resume_id: result.resume_id,
          job_id: jobId,
          to_email: candidateEmail,
          subject: subject.trim(),
          body_html: bodyHtml,
        },
      });

      if (error) throw error;

      if (data?.skipped) {
        toast.warning("Email disabled — candidate marked as rejected without email.");
      } else if (data?.error) {
        throw new Error(data.error);
      } else {
        toast.success(`Rejection email sent to ${candidateName}`);
      }

      // Move to rejected stage
      if (onStageChange) {
        onStageChange(result.resume_id, "rejected" as HiringStage);
      }

      onOpenChange(false);
    } catch (err: any) {
      toast.error(err?.message || "Failed to send rejection email");
    } finally {
      setIsSending(false);
    }
  };

  const handleRejectOnly = () => {
    if (onStageChange) {
      onStageChange(result.resume_id, "rejected" as HiringStage);
    }
    toast.success(`${candidateName} moved to Rejected`);
    onOpenChange(false);
  };

  const mailtoHref = candidateEmail
    ? `mailto:${candidateEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`
    : undefined;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[540px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <UserX className="h-4 w-4 text-destructive" />
            Reject {candidateName}
          </DialogTitle>
        </DialogHeader>

        {!candidateEmail ? (
          <div className="py-4 space-y-3">
            <p className="text-sm text-muted-foreground">
              No email address found for this candidate. They will be moved to
              the Rejected stage without notification.
            </p>
          </div>
        ) : (
          <div className="space-y-4 py-2">
            {/* AI badge */}
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <Sparkles className="h-3 w-3 text-primary" />
              AI-generated feedback based on candidate's profile and gaps
            </div>

            {/* To */}
            <div className="space-y-1.5">
              <Label htmlFor="reject-to">To</Label>
              <Input
                id="reject-to"
                value={candidateEmail}
                readOnly
                className="bg-muted text-muted-foreground cursor-not-allowed"
              />
            </div>

            {/* Subject */}
            <div className="space-y-1.5">
              <Label htmlFor="reject-subject">Subject</Label>
              <Input
                id="reject-subject"
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                disabled={isSending}
              />
            </div>

            {/* Body */}
            <div className="space-y-1.5">
              <Label htmlFor="reject-body">Message</Label>
              <Textarea
                id="reject-body"
                value={bodyText}
                onChange={(e) => setBodyText(e.target.value)}
                rows={10}
                disabled={isSending}
                className="resize-none text-sm"
              />
            </div>
          </div>
        )}

        <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
          {candidateEmail ? (
            <>
              <Button
                variant="ghost"
                size="sm"
                className="text-xs text-muted-foreground"
                onClick={handleRejectOnly}
                disabled={isSending}
              >
                Reject Without Email
              </Button>

              {mailtoHref && (
                <Button variant="outline" size="sm" asChild className="gap-1.5">
                  <a href={mailtoHref} target="_blank" rel="noopener noreferrer">
                    <ExternalLink className="h-3.5 w-3.5" />
                    Open in Email Client
                  </a>
                </Button>
              )}

              <Button
                variant="destructive"
                onClick={handleSendAndReject}
                disabled={isSending}
                className="gap-1.5"
              >
                {isSending ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                ) : (
                  <Mail className="h-3.5 w-3.5" />
                )}
                {isSending ? "Sending..." : "Send & Reject"}
              </Button>
            </>
          ) : (
            <Button
              variant="destructive"
              onClick={handleRejectOnly}
              className="gap-1.5"
            >
              <UserX className="h-3.5 w-3.5" />
              Confirm Rejection
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default RejectCandidateDialog;

