                className="bg-muted text-muted-foreground cursor-not-allowed"
              />
            </div>

            {/* Subject */}
            <div className="space-y-1.5">
              <Label htmlFor="reject-subject">Subject</Label>
              <Input
                id="reject-subject"
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                disabled={isSending}
              />
            </div>

            {/* Body */}
            <div className="space-y-1.5">
              <Label htmlFor="reject-body">Message</Label>
              <Textarea
                id="reject-body"
                value={bodyText}
                onChange={(e) => setBodyText(e.target.value)}
                rows={10}
                disabled={isSending}
                className="resize-none text-sm"
              />
            </div>
          </div>
        )}

        <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
          {candidateEmail ? (
            <>
              <Button
                variant="ghost"
                size="sm"
                className="text-xs text-muted-foreground"
                onClick={handleRejectOnly}
                disabled={isSending}
              >
                Reject Without Email
              </Button>

              {mailtoHref && (
                <Button variant="outline" size="sm" asChild className="gap-1.5">
                  <a href={mailtoHref} target="_blank" rel="noopener noreferrer">
                    <ExternalLink className="h-3.5 w-3.5" />
                    Open in Email Client
                  </a>
                </Button>
              )}

              <Button
                variant="destructive"
                onClick={handleSendAndReject}
                disabled={isSending}
                className="gap-1.5"
              >
                {isSending ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                ) : (
                  <Mail className="h-3.5 w-3.5" />
                )}
                {isSending ? "Sending..." : "Send & Reject"}
              </Button>
            </>
          ) : (
            <Button
              variant="destructive"
              onClick={handleRejectOnly}
              className="gap-1.5"
            >
              <UserX className="h-3.5 w-3.5" />
              Confirm Rejection
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default RejectCandidateDialog;

