import { Phone, Mail, FileText, Archive, MapPin, Download, X, Linkedin, Calendar } from "lucide-react";
import { toast } from "sonner";
import type { Result } from "@/pages/Index";
import type { HiringStage } from "@/hooks/useStageTracker";

import CandidateSummary from "@/components/candidate/CandidateSummary";
import CandidateSummaryCard from "@/components/candidate/CandidateSummaryCard";
import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
import ExperiencePanel from "@/components/candidate/ExperiencePanel";
import EducationPanel from "@/components/candidate/EducationPanel";
import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
import StageTracker from "@/components/candidate/StageTracker";
import ScorecardPanel from "@/components/candidate/ScorecardPanel";
import ScorecardSummary from "@/components/candidate/ScorecardSummary";
import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
import CandidateNotesPanel from "@/components/candidate/CandidateNotesPanel";
import InterviewsPanel from "@/components/candidate/InterviewsPanel";
import ScheduleInterviewDialog from "@/components/ScheduleInterviewDialog";
import RejectCandidateDialog from "@/components/candidate/RejectCandidateDialog";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { extractLinkedInUrl } from "@/lib/linkedin";

interface CandidateDetailSheetProps {
  result: Result | null;
  isOpen: boolean;
  onClose: () => void;
  jobId?: string | null;
  jobTitle?: string | null;
  teamId?: string | null;
  formatCandidateName: (filename: string) => string;
  onDownload: (filePath: string, filename: string) => void;
  onDismiss: (resumeId: string) => void;
  currentStage?: HiringStage | null;
  stageUpdatedAt?: string | null;
  onStageChange?: (resumeId: string, stage: HiringStage) => void;
}

const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

const CandidateDetailSheet = ({
  result: r,
  isOpen,
  onClose,
  jobId,
  jobTitle,
  teamId,
  formatCandidateName,
  onDownload,
  onDismiss,
  currentStage,
  stageUpdatedAt,
  onStageChange,
}: CandidateDetailSheetProps) => {
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
  const [scheduleOpen, setScheduleOpen] = useState(false);
  const [rejectDialogOpen, setRejectDialogOpen] = useState(false);

  if (!r) return null;

  const strength = getStrengthLabel(r.overall_score);
  const linkedinUrl = extractLinkedInUrl(r);
  const candidateName = r.candidate_name || formatCandidateName(r.filename);

  return (
    <>
      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col gap-0 [&>button]:hidden">
          {/* Dark hero header */}
          <div className="bg-foreground text-background px-6 pt-6 pb-5 shrink-0 relative">
            <button onClick={onClose} className="absolute top-4 right-4 rounded-sm opacity-70 hover:opacity-100 transition-opacity">
              <X className="h-4 w-4" />
            </button>

            <div className="space-y-3">
              <div>
                <h2 className="text-xl font-semibold truncate pr-8">{candidateName}</h2>
                <div className="flex items-center gap-2 mt-1 flex-wrap text-background/60">
                  {r.candidate_location && (
                    <span className="flex items-center gap-1 text-xs">
                      <MapPin className="h-3 w-3" /> {r.candidate_location}
                    </span>
                  )}
                  {r.candidate_email && <span className="text-xs">{r.candidate_email}</span>}
                </div>
              </div>

              {/* Score + badge row */}
              <div className="flex items-end gap-4">
                <div>
                  <span className="text-xs text-background/50 block">Overall Match</span>
                  <span className="text-4xl font-bold tabular-nums">{r.overall_score?.toFixed(0)}%</span>
                </div>
                <div className="flex items-center gap-2 pb-1.5">
                  <Badge variant={strength.variant} className="shadow-sm">{strength.label}</Badge>
                  {r.scoring_version === "heuristic" && <Badge variant="secondary">Quick</Badge>}
                  {r.confidence ? <Badge variant="outline" className="text-background/70 border-background/20">{r.confidence}% confidence</Badge> : null}
                </div>
              </div>

              {/* Progress bar */}
              <div className="h-1.5 rounded-full bg-background/20 overflow-hidden">
                <div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${Math.min(r.overall_score, 100)}%` }} />
              </div>
            </div>
          </div>

          {/* Action buttons */}
          <div className="px-6 py-3 flex items-center gap-2 border-b border-border shrink-0 bg-muted/30">
            {r.candidate_phone && (
              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
                <Phone className="h-3 w-3" /> Call
              </Button>
            )}
            {r.candidate_email && (
              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                onClick={() => setEmailDialogOpen(true)}>
                <Mail className="h-3 w-3" /> Email
              </Button>
            )}
            {jobId && (
              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                onClick={() => setScheduleOpen(true)}>
                <Calendar className="h-3 w-3" /> Schedule
              </Button>
            )}
            {r.file_path && (
              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
                onClick={() => onDownload(r.file_path!, r.filename)}>
                <Download className="h-3 w-3" /> Resume
              </Button>
            )}
            {linkedinUrl && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs border-[#0A66C2]/30 text-[#0A66C2] hover:bg-[#0A66C2]/10"
                      onClick={() => window.open(linkedinUrl, "_blank", "noopener,noreferrer")}>
                      <Linkedin className="h-3 w-3" /> LinkedIn
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>View LinkedIn Profile</TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
            <div className="ml-auto">
              <Button variant="ghost" size="sm" className="h-8 gap-1.5 text-xs text-muted-foreground hover:text-destructive"
                onClick={() => { onDismiss(r.resume_id); onClose(); }}>
                <Archive className="h-3 w-3" /> Archive
              </Button>
            </div>
          </div>

          {/* Scrollable panels */}
          <div className="relative flex-1 min-h-0">
            <ScrollArea className="h-full">
              <div className="px-6 py-6 space-y-6">
                {/* 1. Stage — where is this candidate in the pipeline? */}
                {onStageChange && (
                  <StageTracker
                    currentStage={currentStage || "applied"}
                    updatedAt={stageUpdatedAt}
                    onStageChange={(stage) => onStageChange(r.resume_id, stage)}
                  />
                )}

                {/* 2. Team Notes */}
                {jobId && (
                  <CandidateNotesPanel resumeId={r.resume_id} jobId={jobId} />
                )}

                {/* 2b. Scorecard summary — evaluation count + per-criterion averages */}
                {jobId && teamId && (
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">Evaluations</p>
                    <ScorecardSummary resumeId={r.resume_id} jobId={jobId} teamId={teamId} />
                  </div>
                )}

                {/* 2c. Scorecard panel — submit / update evaluation */}
                {jobId && teamId && (
                  <div>
                    <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider mb-2">Your Evaluation</p>
                    <ScorecardPanel resumeId={r.resume_id} jobId={jobId} teamId={teamId} />
                  </div>
                )}

                {/* 3. Rich AI Summary Card — score ring, sub-scores, must-haves, strengths, gaps, interview Qs */}
                <CandidateSummaryCard
                  result={r}
                  candidateName={candidateName}
                  compact={false}
                />

                {/* 4. JD Alignment — the hiring decision: fit or not? */}
                <JDAlignedPanel result={r} />

                {/* 4. Summary — AI's take on this candidate */}
                <CandidateSummary result={r} />

                {/* 5. Strengths & Gaps — quick signal */}
                <StrengthsGapsPanel result={r} />

                {/* 6. Skills — technical depth */}
                <SkillsDetailPanel result={r} />

                {/* 7. Background — experience + education */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
                  <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
                </div>

                {/* 8. Interviews — scheduled interviews for this candidate */}
                {jobId && (
                  <InterviewsPanel
                    resumeId={r.resume_id}
                    jobId={jobId}
                    candidateName={candidateName}
                    candidateEmail={r.candidate_email}
                  />
                )}

                {/* 9. Interview prep — last, for next steps */}
                <InterviewQuestionsPanel result={r} />
              </div>
            </ScrollArea>
            <div className="absolute bottom-0 left-0 right-0 h-8 bg-gradient-to-t from-background to-transparent pointer-events-none" />
          </div>
        </SheetContent>
      </Sheet>

      {r.candidate_email && (
        <EmailOutreachDialog
          open={emailDialogOpen}
          onOpenChange={setEmailDialogOpen}
          candidateName={candidateName}
          candidateEmail={r.candidate_email}
          jobTitle={jobTitle || "Open Position"}
          matchScore={Math.round(r.overall_score ?? 0)}
          resumeId={r.resume_id}
          jobId={jobId || ""}
        />
      )}

      {jobId && (
        <ScheduleInterviewDialog
          open={scheduleOpen}
          onOpenChange={setScheduleOpen}
          jobId={jobId}
          resumeId={r.resume_id}
          candidateName={candidateName}
          candidateEmail={r.candidate_email}
        />
      )}
    </>
  );
};

export default CandidateDetailSheet;

