import { useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";
import {
  Building2,
  Briefcase,
  Upload,
  Users,
  ArrowRight,
  ArrowLeft,
  CheckCircle2,
  Sparkles,
  Rocket,
} from "lucide-react";

interface OnboardingWizardProps {
  open: boolean;
  onComplete: () => void;
  onCreateJob: () => void;
  onGoToTeam: () => void;
  userName: string;
}

const STEPS = [
  { icon: Rocket, title: "Welcome to Rankora", color: "text-primary" },
  { icon: Building2, title: "Your Company", color: "text-blue-500" },
  { icon: Briefcase, title: "How It Works", color: "text-emerald-500" },
  { icon: Sparkles, title: "You're All Set", color: "text-violet-500" },
];

const OnboardingWizard = ({
  open,
  onComplete,
  onCreateJob,
  onGoToTeam,
  userName,
}: OnboardingWizardProps) => {
  const [step, setStep] = useState(0);
  const [companyName, setCompanyName] = useState("");
  const [industry, setIndustry] = useState("");

  const next = () => setStep((s) => Math.min(s + 1, STEPS.length - 1));
  const prev = () => setStep((s) => Math.max(s - 1, 0));

  const isLast = step === STEPS.length - 1;

  return (
    <Dialog open={open} onOpenChange={(o) => { if (!o) onComplete(); }}>
      <DialogContent className="sm:max-w-[520px] p-0 gap-0 overflow-hidden">
        {/* Progress dots */}
        <div className="flex items-center justify-center gap-2 pt-6 pb-2">
          {STEPS.map((_, i) => (
            <div
              key={i}
              className={cn(
                "h-1.5 rounded-full transition-all duration-300",
                i === step ? "w-8 bg-primary" : i < step ? "w-4 bg-primary/40" : "w-4 bg-muted"
              )}
            />
          ))}
        </div>

        {/* Content */}
        <div className="px-8 py-6 min-h-[320px] flex flex-col">

          {/* Step 0: Welcome */}
          {step === 0 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center space-y-4">
              <div className="h-14 w-14 rounded-2xl bg-primary/10 flex items-center justify-center">
                <Rocket className="h-7 w-7 text-primary" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-foreground">
                  Welcome, {userName}!
                </h2>
                <p className="text-sm text-muted-foreground mt-2 max-w-sm mx-auto leading-relaxed">
                  Rankora uses AI to score and rank resumes against your job descriptions.
                  Let's get you set up in under 2 minutes.
                </p>
              </div>
            </div>
          )}

          {/* Step 1: Company info */}
          {step === 1 && (
            <div className="flex-1 space-y-5">
              <div className="flex items-center gap-3">
                <div className="h-10 w-10 rounded-xl bg-blue-50 dark:bg-blue-900/20 flex items-center justify-center shrink-0">
                  <Building2 className="h-5 w-5 text-blue-500" />
                </div>
                <div>
                  <h2 className="text-lg font-bold text-foreground">Tell us about your company</h2>
                  <p className="text-xs text-muted-foreground">This helps personalize your experience.</p>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                <div className="space-y-1.5">
                  <Label htmlFor="ob-company">Company name</Label>
                  <Input
                    id="ob-company"
                    value={companyName}
                    onChange={(e) => setCompanyName(e.target.value)}
                    placeholder="e.g. Acme Corp"
                  />
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="ob-industry">Industry <span className="text-muted-foreground">(optional)</span></Label>
                  <Input
                    id="ob-industry"
                    value={industry}
                    onChange={(e) => setIndustry(e.target.value)}
                    placeholder="e.g. Technology, Healthcare, Finance"
                  />
                </div>
              </div>
            </div>
          )}

          {/* Step 2: How it works */}
          {step === 2 && (
            <div className="flex-1 space-y-5">
              <div className="flex items-center gap-3">
                <div className="h-10 w-10 rounded-xl bg-emerald-50 dark:bg-emerald-900/20 flex items-center justify-center shrink-0">
                  <Briefcase className="h-5 w-5 text-emerald-500" />
                </div>
                <div>
                  <h2 className="text-lg font-bold text-foreground">How Rankora works</h2>
                  <p className="text-xs text-muted-foreground">3 simple steps to rank candidates.</p>
                </div>
              </div>

              <div className="space-y-4 pt-2">
                {[
                  {
                    n: 1,
                    icon: Briefcase,
                    title: "Create a Job",
                    desc: "Paste or generate a job description with AI.",
                    color: "bg-blue-50 dark:bg-blue-900/20 text-blue-500",
                  },
                  {
                    n: 2,
                    icon: Upload,
                    title: "Upload Resumes",
                    desc: "Drag & drop PDFs, DOCX, or import via CSV.",
                    color: "bg-amber-50 dark:bg-amber-900/20 text-amber-500",
                  },
                  {
                    n: 3,
                    icon: Sparkles,
                    title: "Get Rankings",
                    desc: "AI scores each candidate against your requirements.",
                    color: "bg-violet-50 dark:bg-violet-900/20 text-violet-500",
                  },
                ].map(({ n, icon: Icon, title, desc, color }) => (
                  <div key={n} className="flex items-start gap-3">
                    <div className={cn("h-9 w-9 rounded-lg flex items-center justify-center shrink-0", color)}>
                      <Icon className="h-4 w-4" />
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-foreground">{title}</p>
                      <p className="text-xs text-muted-foreground">{desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Step 3: All set */}
          {step === 3 && (
            <div className="flex-1 flex flex-col items-center justify-center text-center space-y-5">
              <div className="h-14 w-14 rounded-2xl bg-emerald-50 dark:bg-emerald-900/20 flex items-center justify-center">
                <CheckCircle2 className="h-7 w-7 text-emerald-500" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-foreground">You're all set!</h2>
                <p className="text-sm text-muted-foreground mt-2 max-w-sm mx-auto leading-relaxed">
                  Start by creating your first job, or invite your team to collaborate.
                </p>
              </div>

              <div className="flex flex-col sm:flex-row gap-2 w-full max-w-xs">
                <Button className="flex-1 gap-1.5" onClick={() => { onComplete(); onCreateJob(); }}>
                  <Briefcase className="h-3.5 w-3.5" /> Create First Job
                </Button>
                <Button variant="outline" className="flex-1 gap-1.5" onClick={() => { onComplete(); onGoToTeam(); }}>
                  <Users className="h-3.5 w-3.5" /> Invite Team
                </Button>
              </div>
            </div>
          )}
        </div>

        {/* Footer nav */}
        {!isLast && (
          <div className="flex items-center justify-between px-8 pb-6 pt-2">
            <Button
              variant="ghost"
              size="sm"
              className="text-xs text-muted-foreground"
              onClick={onComplete}
            >
              Skip
            </Button>
            <div className="flex items-center gap-2">
              {step > 0 && (
                <Button variant="outline" size="sm" className="gap-1.5" onClick={prev}>
                  <ArrowLeft className="h-3 w-3" /> Back
                </Button>
              )}
              <Button size="sm" className="gap-1.5" onClick={next}>
                {step === 0 ? "Get Started" : "Continue"} <ArrowRight className="h-3 w-3" />
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};

export default OnboardingWizard;

