import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { MessageCircle, ExternalLink, Sparkles } from "lucide-react";

interface WhatsAppOutreachDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  candidateName: string;
  candidatePhone: string;
  jobTitle: string;
  matchScore: number;
}

type TemplateKey = "interview_invite" | "status_update" | "custom";

const TEMPLATES: Record<TemplateKey, { label: string; build: (name: string, title: string, score: number) => string }> = {
  interview_invite: {
    label: "Interview Invite",
    build: (name, title, _score) =>
      `Hi ${name},\n\nThank you for applying for the *${title}* position. We'd love to invite you for an interview!\n\nCould you share your availability for this week or next? We're flexible on timing.\n\nLooking forward to hearing from you!`,
  },
  status_update: {
    label: "Application Update",
    build: (name, title, score) =>
      `Hi ${name},\n\nWe wanted to update you on your application for *${title}*.\n\nYour profile scored ${score}% match — we're reviewing all candidates and will be in touch shortly with next steps.\n\nThank you for your patience!`,
  },
  custom: {
    label: "Custom Message",
    build: (name, _title, _score) => `Hi ${name},\n\n`,
  },
};

function formatPhoneForWhatsApp(phone: string): string {
  // Strip all non-digit characters except leading +
  const cleaned = phone.replace(/[^\d+]/g, "");
  // Remove leading + if present (wa.me expects digits only)
  return cleaned.replace(/^\+/, "");
}

const WhatsAppOutreachDialog = ({
  open,
  onOpenChange,
  candidateName,
  candidatePhone,
  jobTitle,
  matchScore,
}: WhatsAppOutreachDialogProps) => {
  const [template, setTemplate] = useState<TemplateKey>("interview_invite");
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (open) {
      setTemplate("interview_invite");
      setMessage(TEMPLATES.interview_invite.build(candidateName, jobTitle, matchScore));
    }
  }, [open, candidateName, jobTitle, matchScore]);

  const handleTemplateChange = (key: TemplateKey) => {
    setTemplate(key);
    setMessage(TEMPLATES[key].build(candidateName, jobTitle, matchScore));
  };

  const handleSend = () => {
    if (!message.trim()) {
      toast.error("Please enter a message");
      return;
    }

    const phone = formatPhoneForWhatsApp(candidatePhone);
    const encoded = encodeURIComponent(message);
    const url = `https://wa.me/${phone}?text=${encoded}`;

    window.open(url, "_blank", "noopener,noreferrer");
    toast.success("Opening WhatsApp...");
    onOpenChange(false);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(message);
    toast.success("Message copied to clipboard");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[540px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MessageCircle className="h-4 w-4 text-[#25D366]" />
            WhatsApp {candidateName}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Phone — read-only */}
          <div className="space-y-1.5">
            <Label htmlFor="wa-phone">Phone</Label>
            <Input
              id="wa-phone"
              value={candidatePhone}
              readOnly
              className="bg-muted text-muted-foreground cursor-not-allowed"
            />
          </div>

          {/* Template selector */}
          <div className="space-y-1.5">
            <Label>Message Template</Label>
            <div className="flex items-center gap-2">
              <Select value={template} onValueChange={(v) => handleTemplateChange(v as TemplateKey)}>
                <SelectTrigger className="h-9">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(TEMPLATES).map(([key, { label }]) => (
                    <SelectItem key={key} value={key}>{label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <div className="flex items-center gap-1 text-xs text-muted-foreground shrink-0">
                <Sparkles className="h-3 w-3 text-primary" />
                AI template
              </div>
            </div>
          </div>

          {/* Message — editable */}
          <div className="space-y-1.5">
            <Label htmlFor="wa-message">Message</Label>
            <Textarea
              id="wa-message"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              rows={8}
              placeholder="Type your message..."
              className="resize-none text-sm"
            />
            <p className="text-[11px] text-muted-foreground">
              Use *asterisks* for bold text in WhatsApp.
            </p>
          </div>
        </div>

        <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
          <Button variant="outline" size="sm" onClick={handleCopy} className="gap-1.5">
            Copy Message
          </Button>
          <Button
            onClick={handleSend}
            className="gap-1.5 bg-[#25D366] hover:bg-[#20BD5A] text-white"
          >
            <ExternalLink className="h-3.5 w-3.5" />
            Open in WhatsApp
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default WhatsAppOutreachDialog;

