import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { Key, Copy, Eye, EyeOff, Plus, Trash2, Webhook, Code2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface ApiKey {
  id: string;
  label: string;
  key: string;
  createdAt: string;
}

interface WebhookEntry {
  id: string;
  url: string;
  events: string[];
  active: boolean;
}

const STORAGE_KEY = "rankora_api_keys";
const WEBHOOK_STORAGE_KEY = "rankora_webhooks";

function generateApiKey(): string {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const prefix = "rk_live_";
  let result = "";
  for (let i = 0; i < 32; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return prefix + result;
}

function loadKeys(): ApiKey[] {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
  } catch { return []; }
}

function saveKeys(keys: ApiKey[]) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(keys));
}

function loadWebhooks(): WebhookEntry[] {
  try {
    return JSON.parse(localStorage.getItem(WEBHOOK_STORAGE_KEY) || "[]");
  } catch { return []; }
}

function saveWebhooks(hooks: WebhookEntry[]) {
  localStorage.setItem(WEBHOOK_STORAGE_KEY, JSON.stringify(hooks));
}

const WEBHOOK_EVENTS = [
  "job.created",
  "ranking.completed",
  "candidate.applied",
  "candidate.rejected",
  "interview.scheduled",
];

const ApiKeysCard = () => {
  const [keys, setKeys] = useState<ApiKey[]>(loadKeys);
  const [webhooks, setWebhooks] = useState<WebhookEntry[]>(loadWebhooks);
  const [newLabel, setNewLabel] = useState("");
  const [revealedId, setRevealedId] = useState<string | null>(null);
  const [newWebhookUrl, setNewWebhookUrl] = useState("");

  const createKey = () => {
    const label = newLabel.trim() || "My API Key";
    const newKey: ApiKey = {
      id: crypto.randomUUID(),
      label,
      key: generateApiKey(),
      createdAt: new Date().toISOString(),
    };
    const updated = [...keys, newKey];
    setKeys(updated);
    saveKeys(updated);
    setNewLabel("");
    setRevealedId(newKey.id);
    toast.success("API key created — copy it now, it won't be shown again in full.");
  };

  const deleteKey = (id: string) => {
    const updated = keys.filter((k) => k.id !== id);
    setKeys(updated);
    saveKeys(updated);
    toast.success("API key deleted");
  };

  const copyKey = (key: string) => {
    navigator.clipboard.writeText(key);
    toast.success("API key copied");
  };

  const maskKey = (key: string) => {
    return key.slice(0, 12) + "..." + key.slice(-4);
  };

  const addWebhook = () => {
    const url = newWebhookUrl.trim();
    if (!url) return;
    try {
      new URL(url);
    } catch {
      toast.error("Please enter a valid URL");
      return;
    }
    const entry: WebhookEntry = {
      id: crypto.randomUUID(),
      url,
      events: ["ranking.completed"],
      active: true,
    };
    const updated = [...webhooks, entry];
    setWebhooks(updated);
    saveWebhooks(updated);
    setNewWebhookUrl("");
    toast.success("Webhook endpoint added");
  };

  const removeWebhook = (id: string) => {
    const updated = webhooks.filter((w) => w.id !== id);
    setWebhooks(updated);
    saveWebhooks(updated);
    toast.success("Webhook removed");
  };

  return (
    <div className="space-y-6">
      {/* API Keys */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <Key className="h-5 w-5 text-primary" />
            <CardTitle className="text-sm font-semibold">API Keys</CardTitle>
          </div>
          <CardDescription>
            Use API keys to integrate Rankora with your tools. Keys have full access to your account.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Existing keys */}
          {keys.length > 0 && (
            <div className="space-y-2">
              {keys.map((k) => (
                <div key={k.id} className="flex items-center gap-2 rounded-lg border border-border/60 px-3 py-2">
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-foreground">{k.label}</p>
                    <code className="text-xs text-muted-foreground font-mono">
                      {revealedId === k.id ? k.key : maskKey(k.key)}
                    </code>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 w-7 p-0"
                    onClick={() => setRevealedId(revealedId === k.id ? null : k.id)}
                  >
                    {revealedId === k.id ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
                  </Button>
                  <Button variant="ghost" size="sm" className="h-7 w-7 p-0" onClick={() => copyKey(k.key)}>
                    <Copy className="h-3.5 w-3.5" />
                  </Button>
                  <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive" onClick={() => deleteKey(k.id)}>
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Create new key */}
          <div className="flex items-center gap-2">
            <Input
              value={newLabel}
              onChange={(e) => setNewLabel(e.target.value)}
              placeholder="Key label (e.g. Zapier, n8n)"
              className="h-9 text-sm"
            />
            <Button size="sm" className="h-9 gap-1.5 shrink-0" onClick={createKey}>
              <Plus className="h-3.5 w-3.5" /> Generate Key
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Webhooks */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <Webhook className="h-5 w-5 text-primary" />
            <CardTitle className="text-sm font-semibold">Webhooks</CardTitle>
          </div>
          <CardDescription>
            Receive real-time notifications when events happen in your account.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Available events */}
          <div>
            <Label className="text-xs font-medium text-muted-foreground mb-2 block">Available Events</Label>
            <div className="flex flex-wrap gap-1.5">
              {WEBHOOK_EVENTS.map((event) => (
                <Badge key={event} variant="secondary" className="text-[11px] font-mono">
                  {event}
                </Badge>
              ))}
            </div>
          </div>

          {/* Existing webhooks */}
          {webhooks.length > 0 && (
            <div className="space-y-2">
              {webhooks.map((wh) => (
                <div key={wh.id} className="flex items-center gap-2 rounded-lg border border-border/60 px-3 py-2">
                  <div className={cn("h-2 w-2 rounded-full shrink-0", wh.active ? "bg-emerald-500" : "bg-muted-foreground/30")} />
                  <code className="text-xs text-foreground font-mono flex-1 truncate">{wh.url}</code>
                  <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive" onClick={() => removeWebhook(wh.id)}>
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          {/* Add webhook */}
          <div className="flex items-center gap-2">
            <Input
              value={newWebhookUrl}
              onChange={(e) => setNewWebhookUrl(e.target.value)}
              placeholder="https://your-app.com/webhook"
              className="h-9 text-sm font-mono"
            />
            <Button size="sm" className="h-9 gap-1.5 shrink-0" onClick={addWebhook}>
              <Plus className="h-3.5 w-3.5" /> Add
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* API Docs quick reference */}
      <Card className="border border-border/60 shadow-sm">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <Code2 className="h-5 w-5 text-primary" />
            <CardTitle className="text-sm font-semibold">API Quick Reference</CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          <div className="rounded-lg bg-muted/40 p-4 space-y-3 text-xs font-mono">
            <div>
              <p className="text-muted-foreground mb-1"># List your jobs</p>
              <p className="text-foreground">GET /api/v1/jobs</p>
            </div>
            <div>
              <p className="text-muted-foreground mb-1"># Get candidates for a job</p>
              <p className="text-foreground">GET /api/v1/jobs/:id/candidates</p>
            </div>
            <div>
              <p className="text-muted-foreground mb-1"># Create a new job</p>
              <p className="text-foreground">POST /api/v1/jobs</p>
            </div>
            <div>
              <p className="text-muted-foreground mb-1"># Authentication header</p>
              <p className="text-foreground">Authorization: Bearer rk_live_...</p>
            </div>
          </div>
          <p className="text-xs text-muted-foreground mt-3">
            Full API documentation available at <span className="font-medium text-foreground">docs.rankora.co/api</span>
          </p>
        </CardContent>
      </Card>
    </div>
  );
};

