import { useState, useEffect, useRef, useCallback } from "react";
import { toast } from "sonner";
import {
  Globe, Copy, ExternalLink, Loader2, Save, Eye, Plus, Trash2,
  Link2, Twitter, Instagram, Facebook, Linkedin, Code2, Info,
  Users, Star, CheckCircle2, Palette, FileText as FileTextIcon, Share2, Briefcase,
} from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
