// ---------------------------------------------------------------------------

interface Benefit {
  icon: string;
  title: string;
  description: string;
}

interface SocialLinks {
  website?: string;
  linkedin?: string;
  twitter?: string;
  instagram?: string;
  facebook?: string;
}

interface CareerPageConfig {
  id: string;
  team_id: string;
  company_name: string | null;
  slug: string | null;
  logo_url: string | null;
  brand_color: string | null;
  tagline: string | null;
  about: string | null;
  is_active: boolean;
  // Enhanced branding
  font_family: string | null;
  custom_css: string | null;
  cover_image_url: string | null;
  // Culture
  culture_title: string | null;
  culture_description: string | null;
  benefits: Benefit[] | null;
  // Social
  social_links: SocialLinks | null;
  // SEO
  meta_description: string | null;
  meta_keywords: string | null;
}

interface CareerJob {
  id: string;
  title: string | null;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  is_published: boolean | null;
  is_featured: boolean | null;
  expires_at: string | null;
  status: string | null;
  view_count: number | null;
  apply_count: number | null;
}

type SlugStatus = "idle" | "checking" | "available" | "taken";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function slugify(name: string): string {
  const raw = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
  if (raw.length < 3) return raw.padEnd(3, "1");
  return raw;
}

// DB constraint only accepts 6-digit hex (#rrggbb).
function isValidHex(value: string): boolean {
  return /^#[0-9A-Fa-f]{6}$/.test(value);
}

