22	  SidebarFooter,
23	  SidebarHeader,
24	  SidebarMenu,
25	  SidebarMenuItem,
26	  SidebarMenuButton,
27	  SidebarSeparator,
28	} from "@/components/ui/sidebar";
29	import { useNavigate, useLocation, Link } from "react-router-dom";
30	import { useAuth } from "@/hooks/useAuth";
31	import { cn } from "@/lib/utils";
32	
33	interface JobSidebarProps {
34	  showDashboard?: boolean;
35	  showMyJobs?: boolean;
36	  onNewJob?: () => void;
37	  onDashboard?: () => void;
38	  onMyJobs?: () => void;
39	  onAuthRequired?: () => void;
40	  isAuthenticated?: boolean;
41	  selectedJobId?: string | null;
42	}
43	
44	function getInitials(email?: string | null): string {
45	  if (!email) return "?";
46	  const name = email.split("@")[0];
47	  const parts = name.split(/[._-]/);
48	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
49	  return name[0]?.toUpperCase() || "?";
50	}
51	
52	function getUserName(email?: string | null): string {
53	  if (!email) return "User";
54	  const name = email.split("@")[0];
55	  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
56	}
57	
58	interface NavItem {
59	  icon: React.ComponentType<{ className?: string }>;
60	  label: string;
61	  isActive: boolean;
62	  onClick: (() => void) | undefined;
63	  show?: boolean;
64	}
65	
66	const NavItemRow = ({ icon: Icon, label, isActive, onClick }: NavItem) => (
67	  <SidebarMenuItem>
68	    <SidebarMenuButton
69	      isActive={isActive}
70	      onClick={onClick}
71	      className={cn(
72	        "h-[34px] gap-2.5 rounded-lg text-[13px] font-medium transition-colors duration-100",
73	        isActive
74	          ? "bg-primary/[0.08] text-primary dark:bg-primary/15"
75	          : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
76	      )}
77	    >
78	      <Icon className={cn("h-4 w-4 shrink-0", isActive ? "text-primary" : "text-muted-foreground/70")} />
79	      <span>{label}</span>
80	    </SidebarMenuButton>
81	  </SidebarMenuItem>
82	);
83	
84	const SectionLabel = ({ children }: { children: string }) => (
85	  <p className="px-3 pt-4 pb-1 text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground/40 select-none">
86	    {children}
87	  </p>
88	);
89	
