102	    { icon: Home, label: "Dashboard", isActive: !!showDashboard, onClick: onDashboard, show: isAuthenticated && !!onDashboard },
103	    { icon: Briefcase, label: "My Jobs", isActive: !!showMyJobs, onClick: onMyJobs, show: isAuthenticated && !!onMyJobs },
104	    { icon: Bookmark, label: "Talent Pool", isActive: pathname === "/talent-pool", onClick: () => navigate("/talent-pool"), show: isAuthenticated },
105	  ];
106	
107	  const toolsNav: NavItem[] = [
108	    { icon: CheckSquare, label: "Tasks", isActive: pathname === "/tasks", onClick: () => navigate("/tasks"), show: isAuthenticated },
109	    { icon: Activity, label: "Activity", isActive: pathname === "/activity", onClick: () => navigate("/activity"), show: isAuthenticated },
110	    { icon: BarChart3, label: "Reports", isActive: pathname === "/reports", onClick: () => navigate("/reports"), show: isAuthenticated },
111	  ];
112	
113	  const orgNav: NavItem[] = [
114	    { icon: Users, label: "Team", isActive: pathname === "/team", onClick: () => navigate("/team") },
115	    { icon: Building2, label: "Agency", isActive: pathname === "/agency", onClick: () => navigate("/agency") },
116	    { icon: Globe, label: "Career Page", isActive: pathname === "/career-settings", onClick: () => navigate("/career-settings") },
117	    { icon: Plug, label: "Integrations", isActive: pathname === "/integrations", onClick: () => navigate("/integrations") },
118	    { icon: CreditCard, label: "Billing", isActive: pathname === "/billing", onClick: () => navigate("/billing") },
119	    { icon: Settings, label: "Settings", isActive: pathname === "/settings", onClick: () => navigate("/settings") },
120	  ];
121	
122	  return (
123	    <Sidebar collapsible="offcanvas" className="border-r border-border/50">
124	      <SidebarHeader className="px-4 py-3">
125	        <button
126	          onClick={onDashboard}
127	          className="flex items-center gap-2.5 rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring w-full text-left"
128	        >
129	          <div className="h-7 w-7 rounded-lg bg-primary flex items-center justify-center shrink-0 shadow-sm">
130	            <Layers className="h-3.5 w-3.5 text-primary-foreground" />
131	          </div>
132	          <div className="flex-1 min-w-0">
133	            <span className="font-semibold text-[13px] text-foreground tracking-tight block leading-tight">Rankora</span>
134	            <span className="text-[10px] text-muted-foreground/60 leading-tight">Hiring Platform</span>
135	          </div>
136	        </button>
137	      </SidebarHeader>
138	
139	      <SidebarSeparator className="mx-3" />
140	
141	      <SidebarContent className="px-2 overflow-y-auto">
142	        <SectionLabel>Workspace</SectionLabel>
143	        <SidebarMenu>
144	          {workspaceNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
145	        </SidebarMenu>
146	
147	        <SectionLabel>Tools</SectionLabel>
148	        <SidebarMenu>
149	          {toolsNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
150	        </SidebarMenu>
151	
152	        {isAuthenticated && (
153	          <>
154	            <SectionLabel>Organization</SectionLabel>
155	            <SidebarMenu>
156	              {orgNav.map((item) => <NavItemRow key={item.label} {...item} />)}
157	            </SidebarMenu>
158	          </>
159	        )}
160	
161	        <SectionLabel>Support</SectionLabel>
162	        <SidebarMenu>
163	          <SidebarMenuItem>
164	            <Link to="/request-feature" className={cn("flex items-center gap-2.5 px-2 h-[34px] rounded-lg text-[13px] font-medium transition-colors duration-100 w-full", pathname === "/request-feature" ? "bg-primary/[0.08] text-primary" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
165	              <Megaphone className="h-4 w-4 shrink-0 text-muted-foreground/70" />
166	              <span>Feature Request</span>
167	            </Link>
168	          </SidebarMenuItem>
169	          <SidebarMenuItem>
170	            <Link to="/changelog" className={cn("flex items-center gap-2.5 px-2 h-[34px] rounded-lg text-[13px] font-medium transition-colors duration-100 w-full", pathname === "/changelog" ? "bg-primary/[0.08] text-primary" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
171	              <FileText className="h-4 w-4 shrink-0 text-muted-foreground/70" />
172	              <span>Changelog</span>
173	            </Link>
174	          </SidebarMenuItem>
175	        </SidebarMenu>
176	      </SidebarContent>
177	
178	      {user && (
179	        <SidebarFooter className="px-3 pb-3 pt-1">
180	          <SidebarSeparator className="mb-2" />
181	          <button
182	            className="flex items-center gap-2.5 px-1.5 py-1.5 rounded-lg hover:bg-sidebar-accent/60 transition-colors w-full text-left"
183	            onClick={() => navigate("/profile")}
