import {
  Briefcase,
  Home,
  Settings,
  CreditCard,
  Users,
  CheckSquare,
  Activity,
  Globe,
  Layers,
  Megaphone,
  FileText,
  Plug,
  BarChart3,
  Building2,
  Bookmark,
  ChevronDown,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarSeparator,
} from "@/components/ui/sidebar";
import { useNavigate, useLocation, Link } from "react-router-dom";
import { useAuth } from "@/hooks/useAuth";
import { cn } from "@/lib/utils";

interface JobSidebarProps {
  showDashboard?: boolean;
  showMyJobs?: boolean;
  onNewJob?: () => void;
  onDashboard?: () => void;
  onMyJobs?: () => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
  selectedJobId?: string | null;
}

function getInitials(email?: string | null): string {
  if (!email) return "?";
  const name = email.split("@")[0];
  const parts = name.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name[0]?.toUpperCase() || "?";
}

function getUserName(email?: string | null): string {
  if (!email) return "User";
  const name = email.split("@")[0];
  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

interface NavItem {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  isActive: boolean;
  onClick: (() => void) | undefined;
  show?: boolean;
}

const NavItemRow = ({ icon: Icon, label, isActive, onClick }: NavItem) => (
  <SidebarMenuItem>
    <SidebarMenuButton
      isActive={isActive}
      onClick={onClick}
      className={cn(
        "h-[34px] gap-2.5 rounded-lg text-[13px] font-medium transition-colors duration-100",
        isActive
          ? "bg-primary/[0.08] text-primary dark:bg-primary/15"
          : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
      )}
    >
      <Icon className={cn("h-4 w-4 shrink-0", isActive ? "text-primary" : "text-muted-foreground/70")} />
      <span>{label}</span>
    </SidebarMenuButton>
  </SidebarMenuItem>
);

const SectionLabel = ({ children }: { children: string }) => (
  <p className="px-3 pt-4 pb-1 text-[10px] font-bold uppercase tracking-[0.1em] text-muted-foreground/40 select-none">
    {children}
  </p>
);

const JobSidebar = ({
  showDashboard,
  showMyJobs,
  onDashboard,
  onMyJobs,
  isAuthenticated = true,
}: JobSidebarProps) => {
  const navigate = useNavigate();
  const { pathname } = useLocation();
  const { user } = useAuth();

  const workspaceNav: NavItem[] = [
    { icon: Home, label: "Dashboard", isActive: !!showDashboard, onClick: onDashboard, show: isAuthenticated && !!onDashboard },
    { icon: Briefcase, label: "My Jobs", isActive: !!showMyJobs, onClick: onMyJobs, show: isAuthenticated && !!onMyJobs },
    { icon: Bookmark, label: "Talent Pool", isActive: pathname === "/talent-pool", onClick: () => navigate("/talent-pool"), show: isAuthenticated },
  ];

  const toolsNav: NavItem[] = [
    { icon: CheckSquare, label: "Tasks", isActive: pathname === "/tasks", onClick: () => navigate("/tasks"), show: isAuthenticated },
    { icon: Activity, label: "Activity", isActive: pathname === "/activity", onClick: () => navigate("/activity"), show: isAuthenticated },
    { icon: BarChart3, label: "Reports", isActive: pathname === "/reports", onClick: () => navigate("/reports"), show: isAuthenticated },
  ];

  const orgNav: NavItem[] = [
    { icon: Users, label: "Team", isActive: pathname === "/team", onClick: () => navigate("/team") },
    { icon: Building2, label: "Agency", isActive: pathname === "/agency", onClick: () => navigate("/agency") },
    { icon: Globe, label: "Career Page", isActive: pathname === "/career-settings", onClick: () => navigate("/career-settings") },
    { icon: Plug, label: "Integrations", isActive: pathname === "/integrations", onClick: () => navigate("/integrations") },
    { icon: CreditCard, label: "Billing", isActive: pathname === "/billing", onClick: () => navigate("/billing") },
    { icon: Settings, label: "Settings", isActive: pathname === "/settings", onClick: () => navigate("/settings") },
  ];

  return (
    <Sidebar collapsible="offcanvas" className="border-r border-border/50">
      <SidebarHeader className="px-4 py-3">
        <button
          onClick={onDashboard}
          className="flex items-center gap-2.5 rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring w-full text-left"
        >
          <div className="h-7 w-7 rounded-lg bg-primary flex items-center justify-center shrink-0 shadow-sm">
            <Layers className="h-3.5 w-3.5 text-primary-foreground" />
          </div>
          <div className="flex-1 min-w-0">
            <span className="font-semibold text-[13px] text-foreground tracking-tight block leading-tight">Rankora</span>
            <span className="text-[10px] text-muted-foreground/60 leading-tight">Hiring Platform</span>
          </div>
        </button>
      </SidebarHeader>

      <SidebarSeparator className="mx-3" />

      <SidebarContent className="px-2 overflow-y-auto">
        <SectionLabel>Workspace</SectionLabel>
        <SidebarMenu>
          {workspaceNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
        </SidebarMenu>

        <SectionLabel>Tools</SectionLabel>
        <SidebarMenu>
          {toolsNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
        </SidebarMenu>

        {isAuthenticated && (
          <>
            <SectionLabel>Organization</SectionLabel>
            <SidebarMenu>
              {orgNav.map((item) => <NavItemRow key={item.label} {...item} />)}
            </SidebarMenu>
          </>
        )}

        <SectionLabel>Support</SectionLabel>
        <SidebarMenu>
          <SidebarMenuItem>
            <Link to="/request-feature" className={cn("flex items-center gap-2.5 px-2 h-[34px] rounded-lg text-[13px] font-medium transition-colors duration-100 w-full", pathname === "/request-feature" ? "bg-primary/[0.08] text-primary" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
              <Megaphone className="h-4 w-4 shrink-0 text-muted-foreground/70" />
              <span>Feature Request</span>
            </Link>
          </SidebarMenuItem>
          <SidebarMenuItem>
            <Link to="/changelog" className={cn("flex items-center gap-2.5 px-2 h-[34px] rounded-lg text-[13px] font-medium transition-colors duration-100 w-full", pathname === "/changelog" ? "bg-primary/[0.08] text-primary" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
              <FileText className="h-4 w-4 shrink-0 text-muted-foreground/70" />
              <span>Changelog</span>
            </Link>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarContent>

      {user && (
        <SidebarFooter className="px-3 pb-3 pt-1">
          <SidebarSeparator className="mb-2" />
          <button
            className="flex items-center gap-2.5 px-1.5 py-1.5 rounded-lg hover:bg-sidebar-accent/60 transition-colors w-full text-left"
            onClick={() => navigate("/profile")}
          >
            <div className="h-8 w-8 rounded-full bg-primary/10 text-primary text-xs font-bold flex items-center justify-center shrink-0 border border-primary/20">
              {getInitials(user.email)}
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-[12px] font-semibold text-foreground truncate leading-tight">{getUserName(user.email)}</p>
              <p className="text-[10px] text-muted-foreground/60 truncate leading-tight">{user.email}</p>
            </div>
            <ChevronDown className="h-3.5 w-3.5 text-muted-foreground/40 shrink-0" />
          </button>
        </SidebarFooter>
      )}
    </Sidebar>
  );
};

export default JobSidebar;

