import React, { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useTheme } from "next-themes";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  LogOut,
  ShieldCheck,
  Sun,
  Moon,
  Monitor,
  User,
  CreditCard,
  Bell,
  Search,
  Sparkles,
} from "lucide-react";
import AuthDialog from "@/components/AuthDialog";
import NotificationBell from "@/components/NotificationBell";

function getInitials(email?: string | null): string {
  if (!email) return "?";
  const name = email.split("@")[0];
  const parts = name.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name[0]?.toUpperCase() || "?";
}

function getUserName(email?: string | null): string {
  if (!email) return "User";
  const name = email.split("@")[0];
  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

const AppHeader = () => {
  const { user, profile, isAdmin, signOut } = useAuth();
  const { theme, setTheme: rawSetTheme } = useTheme();
  const setTheme = (t: string) => {
    document.documentElement.classList.add("disable-transitions");
    rawSetTheme(t);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        document.documentElement.classList.remove("disable-transitions");
      });
    });
  };
  const [authOpen, setAuthOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
  const navigate = useNavigate();

  const openAuth = (tab: "signin" | "signup") => { setAuthTab(tab); setAuthOpen(true); };

  const subCredits = profile?.subscription_credits ?? 0;
  const topCredits = profile?.topup_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + topCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
  const maxCredits = Math.max(totalCredits, 100);
  const creditPercent = Math.min((totalCredits / maxCredits) * 100, 100);

  const initials = getInitials(user?.email);

  return (
    <>
      <header className="border-b border-border/60 bg-background/80 backdrop-blur-sm sticky top-0 z-10">
        <div className="px-4 sm:px-6 flex items-center justify-between h-12">
          {/* Search */}
          <div className="flex-1">
            <button
              className="flex items-center gap-2 h-8 px-3 rounded-lg border border-border/60 bg-muted/30 hover:bg-muted/50 transition-colors text-muted-foreground text-sm max-w-[240px] w-full"
            >
              <Search className="h-3.5 w-3.5 shrink-0" />
              <span className="flex-1 text-left text-xs">Search...</span>
              <kbd className="hidden sm:inline-flex h-5 items-center gap-0.5 rounded border border-border/60 bg-background px-1.5 text-[10px] font-mono text-muted-foreground/60">
                <span className="text-[11px]">&#8984;</span>K
              </kbd>
            </button>
          </div>

          {/* Right actions */}
          <div className="flex items-center gap-1">
            {user ? (
              <>
                <NotificationBell />

                {/* Theme toggle */}
                <div className="hidden sm:flex items-center rounded-lg border border-border/60 bg-muted/30 p-0.5">
                  {([
                    { value: "light", Icon: Sun },
                    { value: "dark", Icon: Moon },
                    { value: "system", Icon: Monitor },
                  ] as const).map(({ value, Icon }) => (
                    <button
                      key={value}
                      onClick={() => setTheme(value)}
                      className={`p-1 rounded-md transition-colors ${
                        theme === value
                          ? "bg-background shadow-sm text-foreground"
                          : "text-muted-foreground hover:text-foreground"
                      }`}
                      aria-label={`${value} theme`}
                    >
                      <Icon className="h-3 w-3" />
                    </button>
                  ))}
                </div>

                {/* Profile dropdown */}
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button
                      className="h-8 w-8 rounded-full bg-primary/10 text-primary text-[11px] font-bold flex items-center justify-center hover:bg-primary/20 transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring border border-primary/20 ml-1"
                      aria-label="Account menu"
                    >
                      {initials}
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-64 mt-1 p-0">
                    {/* User info */}
                    <div className="px-4 py-3 flex items-center gap-3">
                      <div className="h-9 w-9 rounded-full bg-primary/10 text-primary text-xs font-bold flex items-center justify-center shrink-0 border border-primary/20">
                        {initials}
                      </div>
                      <div className="min-w-0">
                        <p className="text-sm font-semibold text-foreground truncate">{getUserName(user.email)}</p>
                        <p className="text-[11px] text-muted-foreground truncate">{user.email}</p>
                      </div>
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/billing")}>
                        <Sparkles className="h-4 w-4 mr-2.5 text-primary" />
                        <span className="text-primary font-medium">
                          {profile?.plan && profile.plan !== "free"
                            ? `${profile.plan.charAt(0).toUpperCase() + profile.plan.slice(1)} Plan`
                            : "Upgrade to Pro"}
                        </span>
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/profile")}>
                        <User className="h-4 w-4 mr-2.5" />
                        Account
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/billing")}>
                        <CreditCard className="h-4 w-4 mr-2.5" />
                        Billing
                      </DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/settings")}>
                        <Bell className="h-4 w-4 mr-2.5" />
                        Notifications
                      </DropdownMenuItem>
                      {isAdmin && (
                        <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/admin")}>
                          <ShieldCheck className="h-4 w-4 mr-2.5" />
                          Admin
                        </DropdownMenuItem>
                      )}
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={signOut}>
                        <LogOut className="h-4 w-4 mr-2.5" />
                        Log out
                      </DropdownMenuItem>
                    </div>

                    <DropdownMenuSeparator className="m-0" />

                    {/* Credits bar */}
                    <div className="px-4 py-3">
                      <div className="flex items-center justify-between mb-1.5">
                        <span className="text-xs font-semibold text-foreground">Credits</span>
                        <button onClick={() => navigate("/billing")} className="text-[11px] text-muted-foreground hover:text-foreground transition-colors">
                          {totalCredits} left &rsaquo;
                        </button>
                      </div>
                      <Progress value={creditPercent} className="h-1.5" />
                    </div>
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            ) : (
              <>
                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>Sign in</Button>
                <Button size="sm" onClick={() => openAuth("signup")}>Sign up free</Button>
              </>
            )}
          </div>
        </div>
      </header>
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </>
  );
};

export default React.memo(AppHeader);

