import {
  Briefcase,
  Home,
  Settings,
  CreditCard,
  Users,
  CheckSquare,
  Activity,
  Globe,
  Layers,
  Megaphone,
  FileText,
  Plug,
  BarChart3,
  Building2,
  Bookmark,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarSeparator,
} from "@/components/ui/sidebar";
import { useNavigate, useLocation, Link } from "react-router-dom";
import { cn } from "@/lib/utils";

interface JobSidebarProps {
  showDashboard?: boolean;
  showMyJobs?: boolean;
  onNewJob?: () => void;
  onDashboard?: () => void;
  onMyJobs?: () => void;
  onAuthRequired?: () => void;
  isAuthenticated?: boolean;
  selectedJobId?: string | null;
}

interface NavItem {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  isActive: boolean;
  onClick: (() => void) | undefined;
  show?: boolean;
}

const NavItemRow = ({ icon: Icon, label, isActive, onClick }: NavItem) => (
  <SidebarMenuItem>
    <SidebarMenuButton
      isActive={isActive}
      onClick={onClick}
      className={cn(
        "h-8 gap-2.5 rounded-md text-[13px] font-medium transition-colors duration-100",
        isActive
          ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold"
          : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60"
      )}
    >
      <Icon className={cn("h-[15px] w-[15px] shrink-0", isActive ? "text-foreground" : "text-muted-foreground")} />
      <span>{label}</span>
    </SidebarMenuButton>
  </SidebarMenuItem>
);

const SectionLabel = ({ children }: { children: string }) => (
  <p className="px-2 pt-5 pb-1.5 text-[10.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground/50 select-none">
    {children}
  </p>
);

const JobSidebar = ({
  showDashboard,
  showMyJobs,
  onDashboard,
  onMyJobs,
  isAuthenticated = true,
}: JobSidebarProps) => {
  const navigate = useNavigate();
  const { pathname } = useLocation();

  const workspaceNav: NavItem[] = [
    { icon: Home, label: "Dashboard", isActive: !!showDashboard, onClick: onDashboard, show: isAuthenticated && !!onDashboard },
    { icon: Briefcase, label: "My Jobs", isActive: !!showMyJobs, onClick: onMyJobs, show: isAuthenticated && !!onMyJobs },
    { icon: Bookmark, label: "Talent Pool", isActive: pathname === "/talent-pool", onClick: () => navigate("/talent-pool"), show: isAuthenticated },
  ];

  const toolsNav: NavItem[] = [
    { icon: CheckSquare, label: "Tasks", isActive: pathname === "/tasks", onClick: () => navigate("/tasks"), show: isAuthenticated },
    { icon: Activity, label: "Activity", isActive: pathname === "/activity", onClick: () => navigate("/activity"), show: isAuthenticated },
    { icon: BarChart3, label: "Reports", isActive: pathname === "/reports", onClick: () => navigate("/reports"), show: isAuthenticated },
  ];

  const orgNav: NavItem[] = [
    { icon: Users, label: "Team", isActive: pathname === "/team", onClick: () => navigate("/team") },
    { icon: Building2, label: "Agency", isActive: pathname === "/agency", onClick: () => navigate("/agency") },
    { icon: Globe, label: "Career Page", isActive: pathname === "/career-settings", onClick: () => navigate("/career-settings") },
    { icon: Plug, label: "Integrations", isActive: pathname === "/integrations", onClick: () => navigate("/integrations") },
    { icon: CreditCard, label: "Billing", isActive: pathname === "/billing", onClick: () => navigate("/billing") },
    { icon: Settings, label: "Settings", isActive: pathname === "/settings", onClick: () => navigate("/settings") },
  ];

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      {/* Brand */}
      <SidebarHeader className="px-4 py-4">
        <button
          onClick={onDashboard}
          className="flex items-center gap-2 outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
        >
          <Layers className="h-5 w-5 text-primary" />
          <span className="font-semibold text-foreground tracking-tight text-base">Rankora</span>
        </button>
      </SidebarHeader>

      <SidebarSeparator />

      {/* Navigation */}
      <SidebarContent className="px-2 py-1">
        <SectionLabel>Workspace</SectionLabel>
        <SidebarMenu>
          {workspaceNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
        </SidebarMenu>

        <SectionLabel>Tools</SectionLabel>
        <SidebarMenu>
          {toolsNav.filter((i) => i.show !== false).map((item) => <NavItemRow key={item.label} {...item} />)}
        </SidebarMenu>

        {isAuthenticated && (
          <>
            <SectionLabel>Organization</SectionLabel>
            <SidebarMenu>
              {orgNav.map((item) => <NavItemRow key={item.label} {...item} />)}
            </SidebarMenu>
          </>
        )}

        <SectionLabel>Support</SectionLabel>
        <SidebarMenu>
          <SidebarMenuItem>
            <Link to="/request-feature" className={cn("flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full", pathname === "/request-feature" ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
              <Megaphone className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
              <span>Feature Request</span>
            </Link>
          </SidebarMenuItem>
          <SidebarMenuItem>
            <Link to="/changelog" className={cn("flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full", pathname === "/changelog" ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60")}>
              <FileText className="h-[15px] w-[15px] shrink-0 text-muted-foreground" />
              <span>Changelog</span>
            </Link>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarContent>
    </Sidebar>
  );
};

export default JobSidebar;

