import React, { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useTheme } from "next-themes";
import { useNavigate, useLocation } from "react-router-dom";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import {
  LogOut,
  ShieldCheck,
  Sun,
  Moon,
  Monitor,
  User,
  CalendarCheck,
} from "lucide-react";
import AuthDialog from "@/components/AuthDialog";
import WalletDropdown from "@/components/WalletDropdown";
import NotificationBell from "@/components/NotificationBell";
import { SidebarTrigger } from "@/components/ui/sidebar";
import { Separator } from "@/components/ui/separator";

function getInitials(email?: string | null): string {
  if (!email) return "?";
  const name = email.split("@")[0];
  const parts = name.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name[0]?.toUpperCase() || "?";
}

function getUserName(email?: string | null): string {
  if (!email) return "User";
  const name = email.split("@")[0];
  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

const ROUTE_LABELS: Record<string, string> = {
  "/": "Dashboard",
  "/jobs": "My Jobs",
  "/profile": "Profile",
  "/billing": "Billing",
  "/settings": "Settings",
  "/team": "Team",
  "/tasks": "Tasks",
  "/activity": "Activity",
  "/career-settings": "Career Page",
  "/integrations": "Integrations",
  "/reports": "Reports",
  "/agency": "Agency",
  "/talent-pool": "Talent Pool",
  "/request-feature": "Feature Request",
  "/changelog": "Changelog",
  "/book-demo": "Book Demo",
  "/admin": "Admin",
};

const AppHeader = () => {
  const { user, profile, isAdmin, signOut } = useAuth();
  const { theme, setTheme: rawSetTheme } = useTheme();
  const setTheme = (t: string) => {
    document.documentElement.classList.add("disable-transitions");
    rawSetTheme(t);
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        document.documentElement.classList.remove("disable-transitions");
      });
    });
  };
  const [authOpen, setAuthOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
  const navigate = useNavigate();
  const { pathname } = useLocation();

  const openAuth = (tab: "signin" | "signup") => { setAuthTab(tab); setAuthOpen(true); };

  const initials = getInitials(user?.email);
  const pageLabel = ROUTE_LABELS[pathname] || null;
  const isSubPage = pathname !== "/" && pageLabel;

  return (
    <>
      <header className="border-b">
        <div className="px-6 sm:px-8 lg:px-10 flex items-center justify-between h-14 gap-4">
          {/* Left — Sidebar trigger + Breadcrumb */}
          <div className="flex items-center gap-2 min-w-0">
            <SidebarTrigger className="-ml-1.5 h-7 w-7" />
            <Separator orientation="vertical" className="h-4 mx-1" />
            <Breadcrumb>
              <BreadcrumbList>
                <BreadcrumbItem>
                  {isSubPage ? (
                    <BreadcrumbLink
                      className="text-xs cursor-pointer hover:text-foreground transition-colors"
                      onClick={() => navigate("/")}
                    >
                      Dashboard
                    </BreadcrumbLink>
                  ) : (
                    <BreadcrumbPage className="text-xs font-medium">
                      Dashboard
                    </BreadcrumbPage>
                  )}
                </BreadcrumbItem>
                {isSubPage && (
                  <>
                    <BreadcrumbSeparator className="[&>svg]:h-3 [&>svg]:w-3" />
                    <BreadcrumbItem>
                      <BreadcrumbPage className="text-xs font-medium">
                        {pageLabel}
                      </BreadcrumbPage>
                    </BreadcrumbItem>
                  </>
                )}
              </BreadcrumbList>
            </Breadcrumb>
          </div>

          {/* Right — Actions */}
          <div className="flex items-center gap-1.5 shrink-0">
            {user ? (
              <>
                <WalletDropdown />
                <NotificationBell />
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button className="h-9 w-9 rounded-lg bg-primary text-primary-foreground text-sm font-bold flex items-center justify-center hover:bg-primary/90 transition-all cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1" aria-label="Account menu">
                      {initials}
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-56 mt-1.5 p-0">
                    <div className="px-4 py-3">
                      <p className="text-sm font-semibold text-foreground">{getUserName(user.email)}</p>
                      <p className="text-xs text-muted-foreground truncate">{user.email}</p>
                    </div>
                    <DropdownMenuSeparator className="m-0" />
                    <div className="px-4 py-2.5 flex items-center justify-between">
                      <span className="text-sm text-foreground">Theme</span>
                      <div className="flex items-center rounded-lg border border-border bg-muted/50 p-0.5">
                        <button onClick={(e) => { e.preventDefault(); setTheme("light"); }} className={`p-1.5 rounded-md transition-colors ${theme === "light" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`} aria-label="Light theme"><Sun className="h-3.5 w-3.5" /></button>
                        <button onClick={(e) => { e.preventDefault(); setTheme("dark"); }} className={`p-1.5 rounded-md transition-colors ${theme === "dark" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`} aria-label="Dark theme"><Moon className="h-3.5 w-3.5" /></button>
                        <button onClick={(e) => { e.preventDefault(); setTheme("system"); }} className={`p-1.5 rounded-md transition-colors ${theme === "system" ? "bg-background shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground"}`} aria-label="System theme"><Monitor className="h-3.5 w-3.5" /></button>
                      </div>
                    </div>
                    <DropdownMenuSeparator className="m-0" />
                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/profile")}><User className="h-4 w-4 mr-2.5" />Profile</DropdownMenuItem>
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/book-demo")}><CalendarCheck className="h-4 w-4 mr-2.5" />Book Demo</DropdownMenuItem>
                      {isAdmin && (<DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={() => navigate("/admin")}><ShieldCheck className="h-4 w-4 mr-2.5" />Admin</DropdownMenuItem>)}
                    </div>
                    <DropdownMenuSeparator className="m-0" />
                    <div className="py-1">
                      <DropdownMenuItem className="px-4 py-2 cursor-pointer" onClick={signOut}><LogOut className="h-4 w-4 mr-2.5" />Log out</DropdownMenuItem>
                    </div>
                  </DropdownMenuContent>
                </DropdownMenu>
              </>
            ) : (
              <>
                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>Sign in</Button>
                <Button size="sm" onClick={() => openAuth("signup")}>Sign up free</Button>
              </>
            )}
          </div>
        </div>
      </header>
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </>
  );
};

export default React.memo(AppHeader);

