30	export function useAgencyPlacements(teamId: string | null) {
31	  const queryClient = useQueryClient();
32	  const queryKey = ["agency_placements", teamId];
33	
34	  const { data, isLoading, error } = useQuery({
35	    queryKey,
36	    queryFn: async (): Promise<AgencyPlacement[]> => {
37	      if (!teamId) return [];
38	      try {
39	        const { data, error } = await (supabase as any)
40	          .from("agency_placements")
41	          .select("*, agency_clients(company_name), agency_mandates(job_title)")
42	          .eq("agency_mandates.team_id", teamId)
43	          .order("created_at", { ascending: false });
44	
45	        if (error) {
46	          // Fallback: try without the team_id filter on joined table
47	          const { data: fallback, error: fallbackErr } = await (supabase as any)
48	            .from("agency_placements")
49	            .select("*, agency_clients(company_name), agency_mandates(job_title)")
