        (prev ?? []).filter((j) => !jobIds.includes(j.id))
      );
    } catch (err: any) {
      toast.error(err?.message || "Failed to delete jobs");
    }
  };

  const requireAuth = useCallback(() => {
    if (!user) { setAuthOpen(true); return true; }
    return false;
  }, [user]);

  return (
    <SidebarProvider className="h-svh overflow-hidden">
      <JobSidebar
        showDashboard={view === "dashboard"}
        showMyJobs={view === "my-jobs" || view === "job-detail"}
        onNewJob={handleNewJob}
        onDashboard={handleGoToDashboard}
        onMyJobs={handleGoToMyJobs}
        onAuthRequired={() => setAuthOpen(true)}
        isAuthenticated={!!user}
      />

      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
        <AppHeader />
        <div className="flex items-center h-10 px-4 md:hidden">
          <SidebarTrigger />
          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
        </div>
        <div className="flex-1 overflow-y-auto">

        {/* Dashboard view */}
        {view === "dashboard" && user ? (
          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
            {/* Hero Section — Greeting + Create Button */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
              <div>
                <h1 className="text-2xl font-bold text-foreground">
                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
                </h1>
                <p className="text-sm text-muted-foreground mt-1">
                  Here's an overview of your hiring activity and insights.
                </p>
              </div>
              <Button className="gap-2" onClick={handleNewJob}>
                <Plus className="h-4 w-4" /> Create Job
              </Button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {[
                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
              ].map((s) => (
                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
                  <CardContent className="px-5 py-4 flex items-center gap-4">
                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
                      <s.icon className="h-5 w-5" />
                    </div>
                    <div>
                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            {/* Recent Jobs */}
            {pastJobs.length > 0 && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
                    View All Jobs →
                  </button>
                </div>
                <div className="grid gap-3">
                  {pastJobs.slice(0, 5).map((job) => (
                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
                        <div className="flex items-center gap-3 min-w-0">
                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                            <Briefcase className="h-4 w-4 text-primary" />
                          </div>
                          <div className="min-w-0">
                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
                            <p className="text-xs text-muted-foreground mt-0.5">
                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
                            </p>
                          </div>
                        </div>
                        <div className="flex items-center gap-3 shrink-0">
                          <Badge
                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
                            className="text-xs"
                          >
                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
                          </Badge>
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            )}

            {/* Getting started guide — show only for new users */}
            {pastJobs.length === 0 && !loadingPastJobs && (
              <Card>
                <CardContent className="px-5 py-4 space-y-3">
                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
                  <div className="space-y-2.5">
                    {[
                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
                    ].map((item) => (
                      <div key={item.step} className="flex items-start gap-3 text-sm">
                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
                        <span className="text-muted-foreground">{item.text}</span>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </main>
        ) : view === "my-jobs" && user ? (
          /* My Jobs view — full management */
          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
              <div className="space-y-1">
                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
              </div>
              <Button className="gap-2 shrink-0" onClick={handleNewJob}>
                <Plus className="h-4 w-4" /> Create Job
              </Button>
            </div>
            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
          </main>
        ) : (
          <JobDetailView
            selectedJobId={selectedJobId}
            selectedJob={selectedJob}
            results={results}
            setResults={setResults}
            existingResumes={existingResumes}
            setExistingResumes={setExistingResumes}
            onJobCreated={handleJobCreated}
            onAuthRequired={() => setAuthOpen(true)}
            isAuthenticated={!!user}
            pastJobs={pastJobs}
            onJobUpdated={handleJobUpdated}
            onBack={handleGoToMyJobs}
          />
        )}
        </div>
        </div>
      </SidebarInset>

      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />

      {user && showOnboarding && (
        <OnboardingWizard
          open={showOnboarding}
          onComplete={completeOnboarding}
          onCreateJob={() => { completeOnboarding(); handleNewJob(); }}
          onGoToTeam={() => { completeOnboarding(); navigate("/team"); }}
          userName={user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0] || "there"}
        />
      )}
    </SidebarProvider>
  );
};

export default Index;

import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import {
  Plus, Send, Loader2, ChevronUp, ArrowRight,
  Share2, Flag, Bookmark,
} from "lucide-react";

// ── Types ──

interface FeatureRequest {
  id: string;
  user_id: string;
  title: string;
  description: string;
  category: string;
  status: string;
  votes: number;
  admin_note: string | null;
  created_at: string;
}

// ── Constants ──

const CATEGORIES = [
  "Feature",
  "Improvement",
  "Integration",
  "UI & Design",
  "Data & Export",
  "API & Integration",
  "Search & Filters",
  "General",
];

const STATUS_TABS = [
  { value: "all", label: "All" },
  { value: "submitted", label: "Under Review" },
  { value: "planned", label: "Planned" },
  { value: "in_progress", label: "In Progress" },
  { value: "done", label: "Done" },
];

const STATUS_STYLES: Record<string, { label: string; dot: string; bg: string; text: string }> = {
  submitted: { label: "Under Review", dot: "bg-amber-500", bg: "bg-amber-50 dark:bg-amber-950/30", text: "text-amber-700 dark:text-amber-400" },
  planned: { label: "Planned", dot: "bg-emerald-600", bg: "bg-emerald-50 dark:bg-emerald-950/30", text: "text-emerald-700 dark:text-emerald-400" },
  in_progress: { label: "In Progress", dot: "bg-blue-500", bg: "bg-blue-50 dark:bg-blue-950/30", text: "text-blue-700 dark:text-blue-400" },
  done: { label: "Done", dot: "bg-stone-600", bg: "bg-stone-100 dark:bg-stone-800/40", text: "text-stone-700 dark:text-stone-300" },
};

function getStatusStyle(status: string) {
  return STATUS_STYLES[status] || STATUS_STYLES.submitted;
}

function StatusBadge({ status }: { status: string }) {
  const s = getStatusStyle(status);
  return (
    <span className={`inline-flex items-center gap-1.5 text-xs font-medium px-2.5 py-0.5 rounded-full ${s.bg} ${s.text}`}>
      <span className={`w-1.5 h-1.5 rounded-full ${s.dot}`} />
      {s.label}
    </span>
  );
}

// ── Main Component ──

const RequestFeature = () => {
  const { user } = useAuth();
  const qc = useQueryClient();

  // Form state
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("Feature");
  const [submitting, setSubmitting] = useState(false);

  // Filter/sort state
  const [statusFilter, setStatusFilter] = useState("all");
  const [sortBy, setSortBy] = useState("most_voted");

  // Detail panel
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // ── Queries ──

  const { data: requests = [], isLoading } = useQuery({
    queryKey: ["feature_requests"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("feature_requests")
        .select("*")
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data as FeatureRequest[];
    },
  });

  const { data: myVotes = [] } = useQuery({
    queryKey: ["my_feature_votes"],
    enabled: !!user,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("feature_request_votes")
        .select("feature_request_id")
        .eq("user_id", user!.id);
      if (error) throw error;
      return (data as { feature_request_id: string }[]).map((v) => v.feature_request_id);
    },
  });

  // ── Derived data ──

  const statusCounts = requests.reduce<Record<string, number>>((acc, r) => {
    acc[r.status] = (acc[r.status] || 0) + 1;
    return acc;
  }, {});

  const filtered = requests
    .filter((r) => statusFilter === "all" || r.status === statusFilter)
    .sort((a, b) => {
      if (sortBy === "most_voted") return b.votes - a.votes;
      return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
    });

  const selected = requests.find((r) => r.id === selectedId) || null;
  const hasVoted = (id: string) => myVotes.includes(id);

  const plannedCount = (statusCounts.planned || 0) + (statusCounts.in_progress || 0);
  const shippedCount = statusCounts.done || 0;

  // ── Actions ──

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) { toast.error("Please enter a title"); return; }
    if (!description.trim()) { toast.error("Please describe your idea"); return; }
    if (!user) { toast.error("Please sign in to submit"); return; }

    setSubmitting(true);
    try {
      const { error } = await (supabase as any).from("feature_requests").insert({
        user_id: user.id,
        title: title.trim(),
        description: description.trim(),
        category,
      });
      if (error) throw error;
      setTitle("");
      setDescription("");
      setCategory("Feature");
      toast.success("Feature request submitted!");
      qc.invalidateQueries({ queryKey: ["feature_requests"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to submit");
    } finally {
      setSubmitting(false);
    }
  };

  const handleVote = async (requestId: string) => {
    if (!user) { toast.error("Please sign in to vote"); return; }
    try {
      const { data, error } = await supabase.rpc("toggle_feature_vote", { p_request_id: requestId });
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["feature_requests"] });
      qc.invalidateQueries({ queryKey: ["my_feature_votes"] });
    } catch (err: any) {
      toast.error(err.message || "Vote failed");
    }
  };

  const handleShare = (r: FeatureRequest) => {
    const url = `${window.location.origin}/request-feature?id=${r.id}`;
    navigator.clipboard.writeText(url);
    toast.success("Link copied to clipboard");
  };

  // ── Render ──

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-8">
        {/* Hero */}
        <div className="space-y-3">
          <p className="text-xs font-semibold uppercase tracking-widest text-primary">Feature Requests</p>
          <h1 className="text-3xl font-bold tracking-tight">What should we build next?</h1>
          <p className="text-muted-foreground">
            Upvote features you want, or suggest something new. We review every request and ship based on community votes.
          </p>
          <div className="flex items-center gap-3 pt-1">
            <Badge variant="outline" className="text-xs font-medium gap-1.5">
              <span className="font-bold">{requests.length}</span> total requests
            </Badge>
            <Badge variant="outline" className="text-xs font-medium gap-1.5">
              <span className="font-bold">{plannedCount}</span> planned
            </Badge>
            <Badge variant="outline" className="text-xs font-medium gap-1.5">
              <span className="font-bold">{shippedCount}</span> shipped
            </Badge>
          </div>
        </div>

        {/* Submit Form */}
        <Card className="border">
          <CardContent className="pt-6">
            <div className="flex items-center gap-3 mb-5">
              <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                <Plus className="h-4 w-4 text-primary" />
              </div>
              <div>
                <p className="font-semibold text-sm">Suggest a feature</p>
                <p className="text-xs text-muted-foreground">Your idea could be in our next release</p>
              </div>
            </div>
            <Separator className="mb-5" />
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <Label className="text-sm font-medium">Title</Label>
                <Input
                  placeholder="Short title, e.g. Export results to CSV"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  maxLength={100}
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-sm font-medium">Description</Label>
                <Textarea
                  placeholder="Describe what it does and why it would be useful..."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  maxLength={2000}
                  className="min-h-[100px]"
                />
              </div>
              <div className="flex items-end gap-3">
                <div className="flex-1 space-y-1.5">
                  <Label className="text-sm font-medium">Category</Label>
                  <Select value={category} onValueChange={setCategory}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {CATEGORIES.map((c) => (
                        <SelectItem key={c} value={c}>{c}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <Button type="submit" disabled={submitting || !user} className="gap-2">
                  {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                  Submit request
                </Button>
              </div>
              {!user && (
                <p className="text-xs text-muted-foreground">Sign in to submit a feature request.</p>
              )}
            </form>
          </CardContent>
        </Card>

        {/* Filters + Sort */}
        <div className="flex items-center justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-2 flex-wrap">
            {STATUS_TABS.map((tab) => {
              const count = tab.value === "all" ? requests.length : (statusCounts[tab.value] || 0);
              const active = statusFilter === tab.value;
              return (
                <button
                  key={tab.value}
                  onClick={() => setStatusFilter(tab.value)}
                  className={`inline-flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-full border transition-colors ${
                    active
                      ? "bg-foreground text-background border-foreground"
                      : "bg-background text-muted-foreground border-border hover:border-foreground/30"
                  }`}
                >
                  {tab.label}
                  <span className={`text-[11px] tabular-nums ${active ? "text-background/70" : "text-muted-foreground/60"}`}>
                    {count}
                  </span>
                </button>
              );
            })}
          </div>
          <Select value={sortBy} onValueChange={setSortBy}>
            <SelectTrigger className="w-[140px] h-8 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="most_voted">Most voted</SelectItem>
              <SelectItem value="newest">Newest</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Request List */}
        <div className="space-y-3">
          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
            </div>
          ) : filtered.length === 0 ? (
            <Card>
              <CardContent className="py-12 text-center text-muted-foreground text-sm">
                {statusFilter === "all"
                  ? "No feature requests yet. Be the first to suggest one!"
                  : "No requests with this status."}
              </CardContent>
            </Card>
          ) : (
            filtered.map((r) => (
              <Card key={r.id} className="border hover:border-border/80 transition-colors">
                <CardContent className="p-4 flex gap-4">
                  {/* Vote Button */}
                  <button
                    onClick={() => handleVote(r.id)}
                    className={`flex flex-col items-center justify-center gap-0.5 w-14 shrink-0 rounded-lg border py-2 transition-colors ${
                      hasVoted(r.id)
                        ? "bg-primary/10 border-primary/30 text-primary"
                        : "bg-background border-border text-muted-foreground hover:border-foreground/30"
                    }`}
                  >
                    <ChevronUp className="h-4 w-4" />
                    <span className="text-sm font-bold tabular-nums">{r.votes}</span>
                    <span className="text-[11px]">vote</span>
                  </button>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-3">
                      <h3 className="font-semibold text-sm leading-snug">{r.title}</h3>
                      <StatusBadge status={r.status} />
                    </div>
                    <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{r.description}</p>
                    <div className="flex items-center justify-between mt-3">
                      <div className="flex items-center gap-2">
                        <Badge variant="secondary" className="text-[11px] font-normal px-2 py-0">{r.category}</Badge>
                        <span className="text-[11px] text-muted-foreground">
                          {new Date(r.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                        </span>
                      </div>
                      <button
                        onClick={() => setSelectedId(r.id)}
                        className="text-[11px] text-muted-foreground hover:text-foreground transition-colors flex items-center gap-1"
                      >
                        View details <ArrowRight className="h-3 w-3" />
                      </button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </main>

      {/* Detail Side Panel */}
      <Sheet open={!!selected} onOpenChange={(o) => !o && setSelectedId(null)}>
        <SheetContent className="sm:max-w-lg w-full overflow-y-auto">
          {selected && (
            <>
              <SheetHeader className="space-y-3 pb-4">
                <div className="flex items-center gap-2 flex-wrap">
                  <StatusBadge status={selected.status} />
                  <Badge variant="secondary" className="text-xs">{selected.category}</Badge>
                </div>
                <SheetTitle className="text-lg leading-snug">{selected.title}</SheetTitle>
                <p className="text-sm text-muted-foreground">{selected.description}</p>
              </SheetHeader>

              <Separator />

              {/* Details Grid */}
              <div className="py-5 space-y-4">
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Details</p>
                <div className="grid grid-cols-2 gap-3">
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Votes</p>
                    <p className="text-lg font-bold">{selected.votes}</p>
                  </div>
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Status</p>
                    <p className="text-sm font-semibold">{getStatusStyle(selected.status).label}</p>
                  </div>
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Category</p>
                    <p className="text-sm font-semibold">{selected.category}</p>
                  </div>
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Submitted</p>
                    <p className="text-sm font-semibold">
                      {new Date(selected.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                    </p>
                  </div>
                </div>
              </div>

              <Separator />

              {/* Activity */}
              {selected.admin_note && (
                <div className="py-5 space-y-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Activity</p>
                  <div className="flex items-start gap-3">
                    <div className="w-2 h-2 rounded-full bg-primary mt-1.5 shrink-0" />
                    <div>
                      <p className="text-sm">{selected.admin_note}</p>
                    </div>
                  </div>
                </div>
              )}

              {/* Bottom Actions */}
              <div className="border-t pt-4 mt-4 flex items-center gap-2">
                <Button
                  variant={hasVoted(selected.id) ? "default" : "outline"}
                  className="flex-1 gap-2"
                  onClick={() => handleVote(selected.id)}
                >
                  <ChevronUp className="h-4 w-4" />
                  {hasVoted(selected.id) ? "Voted" : "Upvote"} · {selected.votes}
                </Button>
                <Button variant="outline" size="icon" onClick={() => handleShare(selected)} title="Share">
                  <Share2 className="h-4 w-4" />
                </Button>
              </div>
            </>
          )}
        </SheetContent>
      </Sheet>
    </SidebarLayout>
  );
};

export default RequestFeature;

import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import {
  Plus, Send, Loader2, ChevronUp, ArrowRight,
  Share2, Flag, Bookmark,
} from "lucide-react";

// ── Types ──

interface FeatureRequest {
  id: string;
  user_id: string;
  title: string;
  description: string;
  category: string;
  status: string;
  votes: number;
  admin_note: string | null;
  created_at: string;
}

// ── Constants ──

const CATEGORIES = [
  "Feature",
  "Improvement",
  "Integration",
  "UI & Design",
  "Data & Export",
  "API & Integration",
  "Search & Filters",
  "General",
];

const STATUS_TABS = [
  { value: "all", label: "All" },
  { value: "submitted", label: "Under Review" },
  { value: "planned", label: "Planned" },
  { value: "in_progress", label: "In Progress" },
  { value: "done", label: "Done" },
];

const STATUS_STYLES: Record<string, { label: string; dot: string; bg: string; text: string }> = {
  submitted: { label: "Under Review", dot: "bg-amber-500", bg: "bg-amber-50 dark:bg-amber-950/30", text: "text-amber-700 dark:text-amber-400" },
  planned: { label: "Planned", dot: "bg-emerald-600", bg: "bg-emerald-50 dark:bg-emerald-950/30", text: "text-emerald-700 dark:text-emerald-400" },
  in_progress: { label: "In Progress", dot: "bg-blue-500", bg: "bg-blue-50 dark:bg-blue-950/30", text: "text-blue-700 dark:text-blue-400" },
  done: { label: "Done", dot: "bg-stone-600", bg: "bg-stone-100 dark:bg-stone-800/40", text: "text-stone-700 dark:text-stone-300" },
};

function getStatusStyle(status: string) {
  return STATUS_STYLES[status] || STATUS_STYLES.submitted;
}

function StatusBadge({ status }: { status: string }) {
  const s = getStatusStyle(status);
  return (
    <span className={`inline-flex items-center gap-1.5 text-xs font-medium px-2.5 py-0.5 rounded-full ${s.bg} ${s.text}`}>
      <span className={`w-1.5 h-1.5 rounded-full ${s.dot}`} />
      {s.label}
    </span>
  );
}

// ── Main Component ──

const RequestFeature = () => {
  const { user } = useAuth();
  const qc = useQueryClient();

  // Form state
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("Feature");
  const [submitting, setSubmitting] = useState(false);

  // Filter/sort state
  const [statusFilter, setStatusFilter] = useState("all");
  const [sortBy, setSortBy] = useState("most_voted");

  // Detail panel
  const [selectedId, setSelectedId] = useState<string | null>(null);

  // ── Queries ──

  const { data: requests = [], isLoading } = useQuery({
    queryKey: ["feature_requests"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("feature_requests")
        .select("*")
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data as FeatureRequest[];
    },
  });

  const { data: myVotes = [] } = useQuery({
    queryKey: ["my_feature_votes"],
    enabled: !!user,
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("feature_request_votes")
        .select("feature_request_id")
        .eq("user_id", user!.id);
      if (error) throw error;
      return (data as { feature_request_id: string }[]).map((v) => v.feature_request_id);
    },
  });

  // ── Derived data ──

  const statusCounts = requests.reduce<Record<string, number>>((acc, r) => {
    acc[r.status] = (acc[r.status] || 0) + 1;
    return acc;
  }, {});

  const filtered = requests
    .filter((r) => statusFilter === "all" || r.status === statusFilter)
    .sort((a, b) => {
      if (sortBy === "most_voted") return b.votes - a.votes;
      return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
    });

  const selected = requests.find((r) => r.id === selectedId) || null;
  const hasVoted = (id: string) => myVotes.includes(id);

  const plannedCount = (statusCounts.planned || 0) + (statusCounts.in_progress || 0);
  const shippedCount = statusCounts.done || 0;

  // ── Actions ──

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) { toast.error("Please enter a title"); return; }
    if (!description.trim()) { toast.error("Please describe your idea"); return; }
    if (!user) { toast.error("Please sign in to submit"); return; }

    setSubmitting(true);
    try {
      const { error } = await (supabase as any).from("feature_requests").insert({
        user_id: user.id,
        title: title.trim(),
        description: description.trim(),
        category,
      });
      if (error) throw error;
      setTitle("");
      setDescription("");
      setCategory("Feature");
      toast.success("Feature request submitted!");
      qc.invalidateQueries({ queryKey: ["feature_requests"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to submit");
    } finally {
      setSubmitting(false);
    }
  };

  const handleVote = async (requestId: string) => {
    if (!user) { toast.error("Please sign in to vote"); return; }
    try {
      const { data, error } = await supabase.rpc("toggle_feature_vote", { p_request_id: requestId });
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["feature_requests"] });
      qc.invalidateQueries({ queryKey: ["my_feature_votes"] });
    } catch (err: any) {
      toast.error(err.message || "Vote failed");
    }
  };

  const handleShare = (r: FeatureRequest) => {
    const url = `${window.location.origin}/request-feature?id=${r.id}`;
    navigator.clipboard.writeText(url);
    toast.success("Link copied to clipboard");
  };

  // ── Render ──

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-8">
        {/* Hero */}
        <div className="space-y-3">
          <p className="text-xs font-semibold uppercase tracking-widest text-primary">Feature Requests</p>
          <h1 className="text-3xl font-bold tracking-tight">What should we build next?</h1>
          <p className="text-muted-foreground">
            Upvote features you want, or suggest something new. We review every request and ship based on community votes.
          </p>
          <div className="flex items-center gap-3 pt-1">
            <Badge variant="outline" className="text-xs font-medium gap-1.5">
              <span className="font-bold">{requests.length}</span> total requests
            </Badge>
            <Badge variant="outline" className="text-xs font-medium gap-1.5">
              <span className="font-bold">{plannedCount}</span> planned
            </Badge>
            <Badge variant="outline" className="text-xs font-medium gap-1.5">
              <span className="font-bold">{shippedCount}</span> shipped
            </Badge>
          </div>
        </div>

        {/* Submit Form */}
        <Card className="border">
          <CardContent className="pt-6">
            <div className="flex items-center gap-3 mb-5">
              <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                <Plus className="h-4 w-4 text-primary" />
              </div>
              <div>
                <p className="font-semibold text-sm">Suggest a feature</p>
                <p className="text-xs text-muted-foreground">Your idea could be in our next release</p>
              </div>
            </div>
            <Separator className="mb-5" />
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-1.5">
                <Label className="text-sm font-medium">Title</Label>
                <Input
                  placeholder="Short title, e.g. Export results to CSV"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  maxLength={100}
                />
              </div>
              <div className="space-y-1.5">
                <Label className="text-sm font-medium">Description</Label>
                <Textarea
                  placeholder="Describe what it does and why it would be useful..."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  maxLength={2000}
                  className="min-h-[100px]"
                />
              </div>
              <div className="flex items-end gap-3">
                <div className="flex-1 space-y-1.5">
                  <Label className="text-sm font-medium">Category</Label>
                  <Select value={category} onValueChange={setCategory}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {CATEGORIES.map((c) => (
                        <SelectItem key={c} value={c}>{c}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <Button type="submit" disabled={submitting || !user} className="gap-2">
                  {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                  Submit request
                </Button>
              </div>
              {!user && (
                <p className="text-xs text-muted-foreground">Sign in to submit a feature request.</p>
              )}
            </form>
          </CardContent>
        </Card>

        {/* Filters + Sort */}
        <div className="flex items-center justify-between gap-4 flex-wrap">
          <div className="flex items-center gap-2 flex-wrap">
            {STATUS_TABS.map((tab) => {
              const count = tab.value === "all" ? requests.length : (statusCounts[tab.value] || 0);
              const active = statusFilter === tab.value;
              return (
                <button
                  key={tab.value}
                  onClick={() => setStatusFilter(tab.value)}
                  className={`inline-flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-full border transition-colors ${
                    active
                      ? "bg-foreground text-background border-foreground"
                      : "bg-background text-muted-foreground border-border hover:border-foreground/30"
                  }`}
                >
                  {tab.label}
                  <span className={`text-[11px] tabular-nums ${active ? "text-background/70" : "text-muted-foreground/60"}`}>
                    {count}
                  </span>
                </button>
              );
            })}
          </div>
          <Select value={sortBy} onValueChange={setSortBy}>
            <SelectTrigger className="w-[140px] h-8 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="most_voted">Most voted</SelectItem>
              <SelectItem value="newest">Newest</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Request List */}
        <div className="space-y-3">
          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
            </div>
          ) : filtered.length === 0 ? (
            <Card className="border border-border/60 shadow-sm">
              <CardContent className="py-12 text-center text-muted-foreground text-sm">
                {statusFilter === "all"
                  ? "No feature requests yet. Be the first to suggest one!"
                  : "No requests with this status."}
              </CardContent>
            </Card>
          ) : (
            filtered.map((r) => (
              <Card key={r.id} className="border hover:border-border/80 transition-colors">
                <CardContent className="p-4 flex gap-4">
                  {/* Vote Button */}
                  <button
                    onClick={() => handleVote(r.id)}
                    className={`flex flex-col items-center justify-center gap-0.5 w-14 shrink-0 rounded-lg border py-2 transition-colors ${
                      hasVoted(r.id)
                        ? "bg-primary/10 border-primary/30 text-primary"
                        : "bg-background border-border text-muted-foreground hover:border-foreground/30"
                    }`}
                  >
                    <ChevronUp className="h-4 w-4" />
                    <span className="text-sm font-bold tabular-nums">{r.votes}</span>
                    <span className="text-[11px]">vote</span>
                  </button>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-3">
                      <h3 className="font-semibold text-sm leading-snug">{r.title}</h3>
                      <StatusBadge status={r.status} />
                    </div>
                    <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{r.description}</p>
                    <div className="flex items-center justify-between mt-3">
                      <div className="flex items-center gap-2">
                        <Badge variant="secondary" className="text-[11px] font-normal px-2 py-0">{r.category}</Badge>
                        <span className="text-[11px] text-muted-foreground">
                          {new Date(r.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                        </span>
                      </div>
                      <button
                        onClick={() => setSelectedId(r.id)}
                        className="text-[11px] text-muted-foreground hover:text-foreground transition-colors flex items-center gap-1"
                      >
                        View details <ArrowRight className="h-3 w-3" />
                      </button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </div>
      </main>

      {/* Detail Side Panel */}
      <Sheet open={!!selected} onOpenChange={(o) => !o && setSelectedId(null)}>
        <SheetContent className="sm:max-w-lg w-full overflow-y-auto">
          {selected && (
            <>
              <SheetHeader className="space-y-3 pb-4">
                <div className="flex items-center gap-2 flex-wrap">
                  <StatusBadge status={selected.status} />
                  <Badge variant="secondary" className="text-xs">{selected.category}</Badge>
                </div>
                <SheetTitle className="text-lg leading-snug">{selected.title}</SheetTitle>
                <p className="text-sm text-muted-foreground">{selected.description}</p>
              </SheetHeader>

              <Separator />

              {/* Details Grid */}
              <div className="py-5 space-y-4">
                <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Details</p>
                <div className="grid grid-cols-2 gap-3">
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Votes</p>
                    <p className="text-lg font-bold">{selected.votes}</p>
                  </div>
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Status</p>
                    <p className="text-sm font-semibold">{getStatusStyle(selected.status).label}</p>
                  </div>
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Category</p>
                    <p className="text-sm font-semibold">{selected.category}</p>
                  </div>
                  <div className="rounded-lg border p-3">
                    <p className="text-[11px] text-muted-foreground">Submitted</p>
                    <p className="text-sm font-semibold">
                      {new Date(selected.created_at).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}
                    </p>
                  </div>
                </div>
              </div>

              <Separator />

              {/* Activity */}
              {selected.admin_note && (
                <div className="py-5 space-y-3">
                  <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Activity</p>
                  <div className="flex items-start gap-3">
                    <div className="w-2 h-2 rounded-full bg-primary mt-1.5 shrink-0" />
                    <div>
                      <p className="text-sm">{selected.admin_note}</p>
                    </div>
                  </div>
                </div>
              )}

              {/* Bottom Actions */}
              <div className="border-t pt-4 mt-4 flex items-center gap-2">
                <Button
                  variant={hasVoted(selected.id) ? "default" : "outline"}
                  className="flex-1 gap-2"
                  onClick={() => handleVote(selected.id)}
                >
                  <ChevronUp className="h-4 w-4" />
                  {hasVoted(selected.id) ? "Voted" : "Upvote"} · {selected.votes}
                </Button>
                <Button variant="outline" size="icon" onClick={() => handleShare(selected)} title="Share">
                  <Share2 className="h-4 w-4" />
                </Button>
              </div>
            </>
          )}
        </SheetContent>
      </Sheet>
    </SidebarLayout>
  );
};

export default RequestFeature;

