import { useEffect, useRef } from "react";
import DOMPurify from "dompurify";
import SidebarLayout from "@/components/SidebarLayout";
import { CalendarCheck, Loader2, Check, Clock, Users, ScanLine } from "lucide-react";
import { usePlatformConfig } from "@/hooks/usePlatformConfig";

/** Renders HTML embed code and executes any <script> tags within it */
function EmbedRenderer({ html }: { html: string }) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    // Sanitize embed HTML — allow iframes and external scripts for booking widgets
    const sanitized = DOMPurify.sanitize(html, {
      ADD_TAGS: ["script", "iframe"],
      ADD_ATTR: ["src", "async", "defer", "allow", "allowfullscreen", "frameborder", "scrolling"],
      FORCE_BODY: true,
    });

    const temp = document.createElement("div");
    temp.innerHTML = sanitized;

    el.innerHTML = "";
    const scripts: HTMLScriptElement[] = [];
    Array.from(temp.childNodes).forEach((node) => {
      if (node instanceof HTMLScriptElement) {
        scripts.push(node);
      } else {
        el.appendChild(node.cloneNode(true));
      }
    });

    // Only execute scripts with external src — strip inline scripts for safety
    scripts.forEach((orig) => {
      if (orig.src) {
        const script = document.createElement("script");
        script.src = orig.src;
        script.async = orig.async;
        el.appendChild(script);
      }
    });

    return () => {
      el.innerHTML = "";
    };
  }, [html]);

  return (
    <div
      ref={containerRef}
      className="w-full min-h-[700px] [&>iframe]:w-full [&>iframe]:min-h-[700px] [&>iframe]:border-0"
    />
  );
}

const HIGHLIGHTS = [
  { icon: Clock, text: "30-min walkthrough" },
  { icon: Users, text: "Tailored to your hiring needs" },
  { icon: ScanLine, text: "See AI ranking in action" },
];

const BookDemo = () => {
  const { data: config, isLoading } = usePlatformConfig();
  const embedCode = config?.booking_embed_url;

  return (
    <SidebarLayout>
      <main className="mx-auto max-w-5xl px-4 sm:px-6 lg:px-8 py-10 space-y-8">
        {/* Hero Section */}
        <div className="text-center space-y-4">
          <div className="inline-flex items-center gap-1.5 bg-primary/10 text-primary text-xs font-semibold px-3 py-1 rounded-full">
            <Check className="h-3 w-3" /> Free, no obligation
          </div>
          <h1 className="text-3xl sm:text-4xl font-bold text-foreground tracking-tight">
            See Rankora in Action
          </h1>
          <p className="text-muted-foreground max-w-lg mx-auto">
            Book a personalized demo with our team. We'll walk you through how Rankora can save hours on resume screening.
          </p>

          {/* Highlights */}
          <div className="flex items-center justify-center gap-6 pt-2 flex-wrap">
            {HIGHLIGHTS.map((h) => (
              <div key={h.text} className="flex items-center gap-2 text-sm text-muted-foreground">
                <div className="w-7 h-7 rounded-lg bg-primary/10 flex items-center justify-center">
                  <h.icon className="h-3.5 w-3.5 text-primary" />
                </div>
                <span>{h.text}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Embed Container */}
        <div className="w-full min-h-[700px] rounded-xl border border-border bg-card overflow-hidden shadow-sm">
          {isLoading ? (
            <div className="flex items-center justify-center h-[700px]">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : embedCode ? (
            <EmbedRenderer html={embedCode} />
          ) : (
            <div className="flex flex-col items-center justify-center h-[700px] text-muted-foreground text-sm gap-3">
              <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center">
                <CalendarCheck className="h-7 w-7 text-primary/50" />
              </div>
              <p className="font-medium">Demo booking is being set up</p>
              <p className="text-xs">Please contact us at <a href="mailto:support@rankora.co" className="text-primary underline">support@rankora.co</a> to schedule a demo.</p>
            </div>
          )}
        </div>
      </main>
    </SidebarLayout>
  );
};

export default BookDemo;

import { useState } from "react";
import AppHeader from "@/components/AppHeader";
import AdminSidebar, { type AdminSection } from "@/components/admin/AdminSidebar";
import AdminErrorBoundary from "@/components/admin/AdminErrorBoundary";
import DashboardTab from "@/components/admin/DashboardTab";
import UsersTab from "@/components/admin/UsersTab";
import BillingTab from "@/components/admin/BillingTab";
import PlatformSettingsTab from "@/components/admin/PlatformSettingsTab";
import EmailSettingsTab from "@/components/admin/EmailSettingsTab";
import AIPromptsTab from "@/components/admin/AIPromptsTab";
import IntegrationsTab from "@/components/admin/IntegrationsTab";
import UsageLogsTab from "@/components/admin/UsageLogsTab";
import AuditLogsTab from "@/components/admin/AuditLogsTab";
import SystemErrorLogsTab from "@/components/admin/SystemErrorLogsTab";
import SeoTab from "@/components/admin/SeoTab";
import ChangelogTab from "@/components/admin/ChangelogTab";

const sectionComponents: Record<AdminSection, React.ComponentType> = {
  dashboard: DashboardTab,
  users: UsersTab,
  billing: BillingTab,
  platform_settings: PlatformSettingsTab,
  email_settings: EmailSettingsTab,
  ai_prompts: AIPromptsTab,
  seo: SeoTab,
  changelog: ChangelogTab,
  integrations: IntegrationsTab,
  logs: UsageLogsTab,
  audit_logs: AuditLogsTab,
  system_errors: SystemErrorLogsTab,
};

const Admin = () => {
  const [section, setSection] = useState<AdminSection>("dashboard");
  const ActiveComponent = sectionComponents[section];

  return (
    <div className="h-svh flex overflow-hidden">
      <AdminSidebar active={section} onSelect={setSection} />
      <div className="flex-1 flex flex-col overflow-hidden">
        <AppHeader />
        <main className="flex-1 overflow-y-auto p-6">
          <AdminErrorBoundary key={section}>
            <ActiveComponent />
          </AdminErrorBoundary>
        </main>
      </div>
    </div>
  );
};

export default Admin;

